import { createJob, updateJob } from '../db/firestore';
import { processContentBatch } from '../workers/contentWorker';
import { logger } from '../utils/logger';

export interface GenerateContentRequest {
  projectId: string;
  queryIds: string[];
  contentType: 'qa' | 'list' | 'compare';
  generateVariations?: boolean;
}

export interface GenerateContentResponse {
  success: boolean;
  jobId: string;
  status: string;
  results?: any[];
  error?: string;
}

export const handleGenerateContent = async (
  request: GenerateContentRequest
): Promise<GenerateContentResponse> => {
  let jobId: string | null = null;

  try {
    const { projectId, queryIds, contentType, generateVariations = false } = request;

    jobId = await createJob({
      projectId,
      jobType: 'content_generation',
      status: 'queued',
      triggerSource: 'user',
      requestedBy: ''
    });

    await logger.info(jobId, `Starting content generation for ${queryIds.length} queries`);

    await updateJob(jobId, { status: 'running' });

    const results = await processContentBatch(jobId, projectId, queryIds, contentType, generateVariations);

    const successCount = results.filter(r => r.success).length;
    const failCount = results.filter(r => !r.success).length;

    await updateJob(jobId, { status: 'done' });

    await logger.info(jobId, `Content generation completed: ${successCount} success, ${failCount} failed`);

    return {
      success: true,
      jobId,
      status: 'done',
      results
    };
  } catch (error) {
    console.error('Error generating content:', error);

    if (jobId) {
      await updateJob(jobId, { status: 'error' });
      await logger.error(jobId, `Content generation failed: ${error}`);
    }

    return {
      success: false,
      jobId: jobId || '',
      status: 'error',
      error: String(error)
    };
  }
};
