import { useState } from 'react';
import { createProject } from '../db/firestore';
import { Loader2, Plus, X } from 'lucide-react';

interface ProjectFormProps {
  onSuccess: () => void;
  onCancel?: () => void;
  onProjectCreated?: () => void;
}

export const ProjectForm = ({ onSuccess, onCancel, onProjectCreated }: ProjectFormProps) => {
  const [name, setName] = useState('');
  const [keyword, setKeyword] = useState('');
  const [targetEntityName, setTargetEntityName] = useState('');
  const [primaryRegion, setPrimaryRegion] = useState('');
  const [secondaryRegionsInput, setSecondaryRegionsInput] = useState('');
  const [category, setCategory] = useState('');
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus('Creating project...');

    try {
      const secondaryRegions = secondaryRegionsInput
        .split(',')
        .map(s => s.trim())
        .filter(Boolean);

      await createProject({
        name,
        targetKeyword: keyword,
        status: 'active',
        ...(targetEntityName && { targetEntityName }),
        ...(primaryRegion && { primaryRegion }),
        ...(secondaryRegions.length > 0 && { secondaryRegions }),
        ...(category && { category })
      });

      setStatus('Project created successfully!');
      setName('');
      setKeyword('');
      setTargetEntityName('');
      setPrimaryRegion('');
      setSecondaryRegionsInput('');
      setCategory('');

      setTimeout(() => {
        onSuccess();
        onProjectCreated?.();
      }, 500);
    } catch (error) {
      setStatus(`Error: ${error}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2">
          <Plus className="w-6 h-6 text-blue-600" />
          <h2 className="text-xl font-semibold text-slate-900">Create New Project</h2>
        </div>
        {onCancel && (
          <button
            onClick={onCancel}
            className="p-1.5 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Project Name <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="OO소아과 GEO"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Target Keyword <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            required
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="판교 소아과"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Target Entity Name
          </label>
          <input
            type="text"
            value={targetEntityName}
            onChange={(e) => setTargetEntityName(e.target.value)}
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="OO소아과"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Primary Region
            </label>
            <input
              type="text"
              value={primaryRegion}
              onChange={(e) => setPrimaryRegion(e.target.value)}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="판교동"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Category
            </label>
            <input
              type="text"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="pediatrics"
            />
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-2">
            Secondary Regions
            <span className="text-slate-400 font-normal ml-1">(쉼표로 구분)</span>
          </label>
          <input
            type="text"
            value={secondaryRegionsInput}
            onChange={(e) => setSecondaryRegionsInput(e.target.value)}
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="삼평동, 백현동"
          />
        </div>

        <div className="flex gap-3 pt-2">
          <button
            type="submit"
            disabled={loading}
            className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg transition-colors disabled:bg-slate-400 disabled:cursor-not-allowed flex items-center justify-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                Creating...
              </>
            ) : (
              'Create Project'
            )}
          </button>
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className="px-4 py-3 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors"
            >
              Cancel
            </button>
          )}
        </div>

        {status && (
          <div className={`p-4 rounded-lg ${loading ? 'bg-blue-50 text-blue-700' : status.startsWith('Error') ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'}`}>
            {status}
          </div>
        )}
      </form>
    </div>
  );
};
