import { useState } from 'react';
import { deleteProject } from '../db/firestore';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { TrendingUp, MessageSquare, Target, Award, Trash2, Lightbulb, Share2, Play, Plus, FolderOpen } from 'lucide-react';
import { InfoTooltip } from './InfoTooltip';
import { EmptyState } from './EmptyState';
import { ProjectShare } from './ProjectShare';
import { ProjectForm } from './ProjectForm';
import { useAuth } from '../contexts/AuthContext';
import { useProject } from '../contexts/ProjectContext';
import { handleGenerateQueries } from '../api/generateQueries';
import { handleRunSimulation } from '../api/runSimulation';
import { Metric } from '../db/firestore';

interface DashboardProps {
  onNavigate: (page: string) => void;
}

export const Dashboard = ({ onNavigate }: DashboardProps) => {
  const { user } = useAuth();
  const { projects, selectedProjectId, selectedProject, setSelectedProjectId, loading, reload } = useProject();

  const [deleting, setDeleting] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [showAnalysisModal, setShowAnalysisModal] = useState(false);
  const [showNewProjectForm, setShowNewProjectForm] = useState(false);
  const [competitors, setCompetitors] = useState('');
  const [analysisLoading, setAnalysisLoading] = useState(false);
  const [analysisStatus, setAnalysisStatus] = useState('');

  const handleDeleteProject = async () => {
    if (!selectedProjectId) return;

    const confirmed = window.confirm(
      '정말로 이 프로젝트를 삭제하시겠습니까? 관련된 모든 데이터(질문, 지표, 답변, 콘텐츠)가 영구적으로 삭제됩니다. 이 작업은 되돌릴 수 없습니다.'
    );

    if (!confirmed) return;

    setDeleting(true);
    try {
      await deleteProject(selectedProjectId);
      await reload();
    } catch (error) {
      console.error('Error deleting project:', error);
      alert(`프로젝트 삭제 실패: ${error instanceof Error ? error.message : '알 수 없는 오류'}`);
    } finally {
      setDeleting(false);
    }
  };

  const handleRunAnalysis = async () => {
    if (!selectedProjectId || !selectedProject) return;

    setAnalysisLoading(true);
    setAnalysisStatus('Generating queries...');

    try {
      const queryResult = await handleGenerateQueries({
        keyword: selectedProject.project.targetKeyword,
        projectId: selectedProjectId
      });

      if (!queryResult.success) {
        throw new Error(queryResult.error || 'Failed to generate queries');
      }

      setAnalysisStatus('Running simulation...');
      const competitorsList = competitors
        .split(',')
        .map(c => c.trim())
        .filter(c => c.length > 0);

      const simResult = await handleRunSimulation({
        projectId: selectedProjectId,
        queryIds: queryResult.queryIds,
        competitors: competitorsList
      });

      if (!simResult.success) {
        throw new Error(simResult.error || 'Failed to run simulation');
      }

      setAnalysisStatus('Analysis completed successfully!');
      setCompetitors('');

      setTimeout(() => {
        setShowAnalysisModal(false);
        setAnalysisStatus('');
        reload();
      }, 1500);
    } catch (error) {
      setAnalysisStatus(`Error: ${error}`);
    } finally {
      setAnalysisLoading(false);
    }
  };

  const calculateStats = (metrics: Metric[]) => {
    const total = metrics.length;
    if (total === 0) return { mentionRate: 0, top3Rate: 0, recommendedRate: 0, avgScore: 0 };

    const mentions = metrics.filter(m => m.mention).length;
    const top3 = metrics.filter(m => m.position !== null && m.position <= 3).length;
    const recommended = metrics.filter(m => m.isRecommended).length;
    const totalScore = metrics.reduce((sum, m) => sum + m.score, 0);

    return {
      mentionRate: (mentions / total) * 100,
      top3Rate: (top3 / total) * 100,
      recommendedRate: (recommended / total) * 100,
      avgScore: totalScore / total
    };
  };

  const getChartData = (metrics: Metric[]) => {
    const mentionCount = metrics.filter(m => m.mention).length;
    const noMentionCount = metrics.length - mentionCount;

    return [
      { name: '언급됨', value: mentionCount, color: '#10b981' },
      { name: '언급 안됨', value: noMentionCount, color: '#ef4444' }
    ];
  };

  const getScoreDistribution = (metrics: Metric[]) => {
    const ranges = [
      { name: '낮음\n(0-20)', min: 0, max: 20 },
      { name: '다소 낮음\n(21-40)', min: 21, max: 40 },
      { name: '보통\n(41-60)', min: 41, max: 60 },
      { name: '좋음\n(61-80)', min: 61, max: 80 },
      { name: '매우 좋음\n(81-100)', min: 81, max: 100 }
    ];

    return ranges.map(range => ({
      name: range.name,
      count: metrics.filter(m => m.score >= range.min && m.score <= range.max).length
    }));
  };

  const getInsight = (stats: ReturnType<typeof calculateStats>, totalQueries: number) => {
    const { mentionRate, top3Rate, avgScore } = stats;

    if (totalQueries === 0) {
      return {
        type: 'info' as const,
        message: '아직 분석 데이터가 없습니다. 시뮬레이션을 실행해주세요.'
      };
    }

    if (mentionRate >= 70 && avgScore >= 70) {
      return {
        type: 'success' as const,
        message: `훌륭합니다! AI가 ${totalQueries}개 질문 중 ${Math.round(totalQueries * mentionRate / 100)}개에서 여러분의 브랜드를 언급하고 있습니다.`
      };
    }

    if (mentionRate < 30) {
      return {
        type: 'warning' as const,
        message: `브랜드 노출률이 낮습니다. 콘텐츠 생성을 통해 AI의 인식을 개선해보세요.`
      };
    }

    if (top3Rate < 20 && mentionRate >= 40) {
      return {
        type: 'info' as const,
        message: `브랜드는 언급되지만 상위 추천이 부족합니다. 경쟁력 있는 콘텐츠가 필요합니다.`
      };
    }

    return {
      type: 'info' as const,
      message: `현재 ${totalQueries}개 질문을 분석 중입니다. 더 많은 데이터로 정확도를 높여보세요.`
    };
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
          <p className="text-slate-600">데이터 로딩 중...</p>
        </div>
      </div>
    );
  }

  if (projects.length === 0) {
    return (
      <div className="min-h-screen bg-slate-50">
        <div className="max-w-7xl mx-auto px-4 py-8">
          <div className="mb-8 flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-slate-900 mb-2">Projects</h1>
              <p className="text-slate-600">프로젝트를 생성하고 AI 브랜드 인식을 분석하세요</p>
            </div>
          </div>
          {showNewProjectForm ? (
            <ProjectForm
              onSuccess={async () => {
                setShowNewProjectForm(false);
                await reload();
              }}
              onCancel={() => setShowNewProjectForm(false)}
            />
          ) : (
            <div className="flex flex-col items-center justify-center py-24 gap-6">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center">
                <FolderOpen className="w-8 h-8 text-slate-400" />
              </div>
              <div className="text-center">
                <p className="text-lg font-medium text-slate-700 mb-1">프로젝트가 없습니다</p>
                <p className="text-slate-500 text-sm">새 프로젝트를 생성하여 AI 브랜드 분석을 시작하세요</p>
              </div>
              <button
                onClick={() => setShowNewProjectForm(true)}
                className="px-5 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <Plus className="w-4 h-4" />
                새 프로젝트 만들기
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  const stats = selectedProject ? calculateStats(selectedProject.metrics) : null;
  const chartData = selectedProject ? getChartData(selectedProject.metrics) : [];
  const scoreData = selectedProject ? getScoreDistribution(selectedProject.metrics) : [];
  const insight = stats && selectedProject ? getInsight(stats, selectedProject.queries.length) : null;

  return (
    <div className="min-h-screen bg-slate-50">
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-6 flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h1 className="text-2xl font-bold text-slate-900 mb-0.5">Projects</h1>
            <p className="text-slate-500 text-sm">접근 가능한 프로젝트를 선택하거나 새로 만드세요</p>
          </div>
          <button
            onClick={() => setShowNewProjectForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 text-sm font-medium flex-shrink-0"
          >
            <Plus className="w-4 h-4" />
            새 프로젝트
          </button>
        </div>

        {showNewProjectForm && (
          <div className="mb-6">
            <ProjectForm
              onSuccess={async () => {
                setShowNewProjectForm(false);
                await reload();
              }}
              onCancel={() => setShowNewProjectForm(false)}
            />
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
          {projects.map(({ project, metrics, queries }) => {
            const isSelected = project.id === selectedProjectId;
            const projectStats = calculateStats(metrics);
            return (
              <div
                key={project.id}
                onClick={() => setSelectedProjectId(project.id!)}
                className={`bg-white rounded-xl border-2 p-5 cursor-pointer transition-all ${
                  isSelected
                    ? 'border-blue-500 shadow-md'
                    : 'border-slate-200 hover:border-slate-300 hover:shadow-sm'
                }`}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="min-w-0">
                    <h3 className="font-semibold text-slate-900 truncate">{project.name}</h3>
                    <p className="text-xs text-slate-500 mt-0.5 truncate">{project.targetKeyword}</p>
                  </div>
                  {isSelected && (
                    <div className="w-2 h-2 rounded-full bg-blue-500 mt-1.5 flex-shrink-0" />
                  )}
                </div>
                <div className="grid grid-cols-3 gap-2 text-center mb-3">
                  <div>
                    <p className="text-lg font-bold text-slate-800">{queries.length}</p>
                    <p className="text-xs text-slate-500">쿼리</p>
                  </div>
                  <div>
                    <p className="text-lg font-bold text-slate-800">{metrics.length}</p>
                    <p className="text-xs text-slate-500">측정값</p>
                  </div>
                  <div>
                    <p className="text-lg font-bold text-slate-800">
                      {metrics.length > 0 ? `${projectStats.mentionRate.toFixed(0)}%` : '-'}
                    </p>
                    <p className="text-xs text-slate-500">노출률</p>
                  </div>
                </div>
                <div className="flex items-center justify-between">
                  <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                    project.status === 'active' ? 'bg-green-100 text-green-700' :
                    'bg-slate-100 text-slate-600'
                  }`}>
                    {project.status === 'active' ? '활성' : '보관'}
                  </span>
                  {project.userId !== user?.uid && (
                    <span className="text-xs text-slate-400">공유됨</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {selectedProject && (
          <>
            <div className="mb-6 flex items-center gap-3 pb-4 border-b border-slate-200">
              <h2 className="text-lg font-semibold text-slate-800 flex-1">
                {selectedProject.project.name} — 분석 현황
              </h2>
              <button
                onClick={() => setShowAnalysisModal(true)}
                className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <Play className="w-4 h-4" />
                Run Analysis
              </button>
              <button
                onClick={() => setShowShareModal(true)}
                className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <Share2 className="w-4 h-4" />
                공유
              </button>
              <button
                onClick={handleDeleteProject}
                disabled={deleting || selectedProject.project.userId !== user?.uid}
                className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 disabled:bg-slate-300 disabled:cursor-not-allowed transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <Trash2 className="w-4 h-4" />
                {deleting ? '삭제 중...' : '삭제'}
              </button>
              <button
                onClick={() => onNavigate('queries')}
                className="px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm font-medium"
              >
                Queries 보기 →
              </button>
            </div>

            {insight && (
              <div className={`mb-6 p-4 rounded-lg border-l-4 ${
                insight.type === 'success' ? 'bg-green-50 border-green-500' :
                insight.type === 'warning' ? 'bg-yellow-50 border-yellow-500' :
                'bg-blue-50 border-blue-500'
              }`}>
                <div className="flex items-start gap-3">
                  <Lightbulb className={`w-5 h-5 mt-0.5 ${
                    insight.type === 'success' ? 'text-green-600' :
                    insight.type === 'warning' ? 'text-yellow-600' :
                    'text-blue-600'
                  }`} />
                  <p className={`text-sm font-medium ${
                    insight.type === 'success' ? 'text-green-800' :
                    insight.type === 'warning' ? 'text-yellow-800' :
                    'text-blue-800'
                  }`}>
                    {insight.message}
                  </p>
                </div>
              </div>
            )}

            {stats && selectedProject.metrics.length > 0 ? (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                  <StatCard
                    icon={<Target className="w-6 h-6" />}
                    title="브랜드 노출률"
                    value={`${stats.mentionRate.toFixed(1)}%`}
                    color="bg-blue-500"
                    tooltip="AI가 답변에서 여러분의 브랜드를 언급한 비율입니다."
                    status={stats.mentionRate >= 60 ? 'good' : stats.mentionRate >= 30 ? 'medium' : 'low'}
                  />
                  <StatCard
                    icon={<Award className="w-6 h-6" />}
                    title="상위 추천률"
                    value={`${stats.top3Rate.toFixed(1)}%`}
                    color="bg-green-500"
                    tooltip="AI가 답변에서 여러분의 브랜드를 1~3위 안에 추천한 비율입니다."
                    status={stats.top3Rate >= 40 ? 'good' : stats.top3Rate >= 20 ? 'medium' : 'low'}
                  />
                  <StatCard
                    icon={<TrendingUp className="w-6 h-6" />}
                    title="추천 문장 포함률"
                    value={`${stats.recommendedRate.toFixed(1)}%`}
                    color="bg-amber-500"
                    tooltip="AI가 추천 형태의 문장으로 여러분의 브랜드를 언급한 비율입니다."
                    status={stats.recommendedRate >= 50 ? 'good' : stats.recommendedRate >= 25 ? 'medium' : 'low'}
                  />
                  <StatCard
                    icon={<MessageSquare className="w-6 h-6" />}
                    title="종합 점수"
                    value={stats.avgScore.toFixed(1)}
                    color="bg-slate-500"
                    tooltip="브랜드의 전반적인 AI 인식도 점수입니다."
                    status={stats.avgScore >= 60 ? 'good' : stats.avgScore >= 30 ? 'medium' : 'low'}
                  />
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div className="bg-white rounded-lg shadow p-6">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="text-lg font-semibold text-slate-800">브랜드 언급 분포</h3>
                      <InfoTooltip text="AI 답변에서 브랜드가 언급된 횟수와 언급되지 않은 횟수를 비교합니다." />
                    </div>
                    <p className="text-sm text-slate-600 mb-4">
                      총 {selectedProject.metrics.length}개 질문 중 {chartData[0]?.value || 0}개에서 언급됨
                    </p>
                    <ResponsiveContainer width="100%" height={300}>
                      <PieChart>
                        <Pie
                          data={chartData}
                          cx="50%"
                          cy="50%"
                          labelLine={false}
                          label={(entry) => `${entry.name}: ${entry.value}개`}
                          outerRadius={100}
                          fill="#8884d8"
                          dataKey="value"
                        >
                          {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={entry.color} />
                          ))}
                        </Pie>
                        <Tooltip formatter={(value) => `${value}개`} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>

                  <div className="bg-white rounded-lg shadow p-6">
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="text-lg font-semibold text-slate-800">점수 분포</h3>
                      <InfoTooltip text="브랜드 점수가 어떤 구간에 분포되어 있는지 보여줍니다." />
                    </div>
                    <p className="text-sm text-slate-600 mb-4">점수 구간별 질문 개수</p>
                    <ResponsiveContainer width="100%" height={300}>
                      <BarChart data={scoreData}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="name" tick={{ fontSize: 12 }} interval={0} />
                        <YAxis label={{ value: '개수', angle: -90, position: 'insideLeft' }} />
                        <Tooltip formatter={(value) => `${value}개`} />
                        <Bar dataKey="count" fill="#3b82f6" />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </>
            ) : (
              <EmptyState type="no-data" />
            )}
          </>
        )}

        {showShareModal && selectedProject && (
          <ProjectShare
            project={selectedProject.project}
            onClose={() => setShowShareModal(false)}
          />
        )}

        {showAnalysisModal && selectedProject && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-lg w-full p-6">
              <h3 className="text-xl font-semibold text-slate-900 mb-4">Run Analysis</h3>
              <p className="text-sm text-slate-600 mb-1">
                프로젝트: <span className="font-medium">{selectedProject.project.name}</span>
              </p>
              <p className="text-sm text-slate-600 mb-4">
                키워드: <span className="font-medium">{selectedProject.project.targetKeyword}</span>
              </p>

              <div className="mb-4">
                <label className="block text-sm font-medium text-slate-700 mb-2">
                  Competitors (comma-separated, optional)
                </label>
                <input
                  type="text"
                  value={competitors}
                  onChange={(e) => setCompetitors(e.target.value)}
                  disabled={analysisLoading}
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-slate-100"
                  placeholder="경쟁사A, 경쟁사B, 경쟁사C"
                />
              </div>

              {analysisStatus && (
                <div className={`mb-4 p-3 rounded-lg text-sm ${
                  analysisLoading ? 'bg-blue-50 text-blue-700' :
                  analysisStatus.includes('Error') ? 'bg-red-50 text-red-700' :
                  'bg-green-50 text-green-700'
                }`}>
                  {analysisStatus}
                </div>
              )}

              <div className="flex gap-3 justify-end">
                <button
                  onClick={() => {
                    setShowAnalysisModal(false);
                    setCompetitors('');
                    setAnalysisStatus('');
                  }}
                  disabled={analysisLoading}
                  className="px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleRunAnalysis}
                  disabled={analysisLoading}
                  className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 disabled:bg-slate-300 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
                >
                  {analysisLoading ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      Running...
                    </>
                  ) : (
                    <>
                      <Play className="w-4 h-4" />
                      Run Analysis
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

interface StatCardProps {
  icon: React.ReactNode;
  title: string;
  value: string;
  color: string;
  tooltip: string;
  status: 'good' | 'medium' | 'low';
}

const StatCard = ({ icon, title, value, color, tooltip, status }: StatCardProps) => {
  const statusColors = {
    good: 'border-green-500 bg-green-50',
    medium: 'border-yellow-500 bg-yellow-50',
    low: 'border-red-500 bg-red-50'
  };

  const statusLabels = {
    good: '좋음',
    medium: '보통',
    low: '개선 필요'
  };

  const statusTextColors = {
    good: 'text-green-700',
    medium: 'text-yellow-700',
    low: 'text-red-700'
  };

  return (
    <div className={`bg-white rounded-lg shadow p-6 border-l-4 ${statusColors[status]}`}>
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-1">
          <p className="text-sm font-medium text-slate-700">{title}</p>
          <InfoTooltip text={tooltip} />
        </div>
        <div className={`${color} text-white p-2 rounded-lg`}>
          {icon}
        </div>
      </div>
      <div className="flex items-end justify-between">
        <p className="text-3xl font-bold text-slate-900">{value}</p>
        <span className={`text-xs font-medium px-2 py-1 rounded ${statusTextColors[status]}`}>
          {statusLabels[status]}
        </span>
      </div>
    </div>
  );
};
