import { createJob, updateJob } from '../db/firestore';
import { processAnswerBatch } from '../workers/answerWorker';
import { logger } from '../utils/logger';

export interface RunSimulationRequest {
  projectId: string;
  queryIds: string[];
  competitors?: string[];
}

export interface RunSimulationResponse {
  success: boolean;
  jobId: string;
  status: string;
  results?: any[];
  error?: string;
}

export const handleRunSimulation = async (
  request: RunSimulationRequest
): Promise<RunSimulationResponse> => {
  let jobId: string | null = null;

  try {
    const { projectId, queryIds, competitors = [] } = request;

    jobId = await createJob({
      projectId,
      jobType: 'answer_simulation',
      status: 'queued',
      triggerSource: 'user',
      requestedBy: ''
    });

    await logger.info(jobId, `Starting simulation for ${queryIds.length} queries`);

    await updateJob(jobId, { status: 'running' });

    const results = await processAnswerBatch(jobId, projectId, queryIds, competitors);

    const successCount = results.filter(r => r.success).length;
    const failCount = results.filter(r => !r.success).length;

    await updateJob(jobId, { status: 'done' });

    await logger.info(jobId, `Simulation completed: ${successCount} success, ${failCount} failed`);

    return {
      success: true,
      jobId,
      status: 'done',
      results
    };
  } catch (error) {
    console.error('Error running simulation:', error);

    if (jobId) {
      await updateJob(jobId, { status: 'error' });
      await logger.error(jobId, `Simulation failed: ${error}`);
    }

    return {
      success: false,
      jobId: jobId || '',
      status: 'error',
      error: String(error)
    };
  }
};
