import { useState } from 'react';
import { LoginPage } from './components/LoginPage';
import Navigation from './components/Navigation';
import ProjectsPage from './pages/ProjectsPage';
import QueriesPage from './pages/QueriesPage';
import AIAnswersPage from './pages/AIAnswersPage';
import ProblemsPage from './pages/ProblemsPage';
import ActionsPage from './pages/ActionsPage';
import PerformancePage from './pages/PerformancePage';
import AutomationPage from './pages/AutomationPage';
import MigrationPage from './pages/MigrationPage';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import { ProjectProvider } from './contexts/ProjectContext';

function AppContent() {
  const { user, loading } = useAuth();
  const [currentPage, setCurrentPage] = useState('projects');

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
          <p className="text-slate-600">로딩중...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <LoginPage />;
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'projects':
        return <ProjectsPage onNavigate={setCurrentPage} />;
      case 'queries':
        return <QueriesPage />;
      case 'ai-answers':
        return <AIAnswersPage />;
      case 'problems':
        return <ProblemsPage />;
      case 'actions':
        return <ActionsPage />;
      case 'performance':
        return <PerformancePage />;
      case 'automation':
        return <AutomationPage />;
      case 'migration':
        return <MigrationPage />;
      default:
        return <ProjectsPage onNavigate={setCurrentPage} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <Navigation currentPage={currentPage} onNavigate={setCurrentPage} user={user} />
      <main className="lg:pl-64">
        {renderPage()}
      </main>
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <ProjectProvider>
        <AppContent />
      </ProjectProvider>
    </AuthProvider>
  );
}

export default App;
