import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { getAllProjects, getMetricsByProject, getQueriesByProject, Project, Metric, QueryDoc } from '../db/firestore';
import { useAuth } from './AuthContext';

export interface ProjectStats {
  project: Project;
  metrics: Metric[];
  queries: QueryDoc[];
}

interface ProjectContextType {
  projects: ProjectStats[];
  selectedProjectId: string | null;
  selectedProject: ProjectStats | undefined;
  setSelectedProjectId: (id: string | null) => void;
  loading: boolean;
  reload: () => Promise<void>;
}

const ProjectContext = createContext<ProjectContextType | null>(null);

export function ProjectProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [projects, setProjects] = useState<ProjectStats[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const loadProjects = async () => {
    if (!user) {
      setProjects([]);
      setLoading(false);
      return;
    }
    try {
      setLoading(true);
      const allProjects = await getAllProjects();
      const projectsWithStats = await Promise.all(
        allProjects.map(async (project) => {
          const [metrics, queries] = await Promise.all([
            getMetricsByProject(project.id!).catch(e => {
              console.error(`[jkai011_projects/${project.id}/jkai011_metrics] permission error:`, e);
              return [] as Metric[];
            }),
            getQueriesByProject(project.id!).catch(e => {
              console.error(`[jkai011_projects/${project.id}/jkai011_queries] permission error:`, e);
              return [] as QueryDoc[];
            }),
          ]);
          return { project, metrics, queries };
        })
      );
      setProjects(projectsWithStats);
      setSelectedProjectId(prev => {
        if (prev && projectsWithStats.find(p => p.project.id === prev)) return prev;
        return projectsWithStats.length > 0 ? projectsWithStats[0].project.id! : null;
      });
    } catch (error) {
      console.error('Error loading projects [jkai011_projects]:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProjects();
  }, [user]);

  const selectedProject = projects.find(p => p.project.id === selectedProjectId);

  return (
    <ProjectContext.Provider value={{
      projects,
      selectedProjectId,
      selectedProject,
      setSelectedProjectId,
      loading,
      reload: loadProjects,
    }}>
      {children}
    </ProjectContext.Provider>
  );
}

export function useProject() {
  const ctx = useContext(ProjectContext);
  if (!ctx) throw new Error('useProject must be used within ProjectProvider');
  return ctx;
}
