import { useState, useEffect } from "react";
import { RefreshCw, AlertCircle, ChevronDown, ChevronUp, CheckCircle } from "lucide-react";
import { useProject } from "../contexts/ProjectContext";
import { getProblemsByProject, updateProblem, Problem } from "../db/firestore";
import { analyzeProblems, getAIProblemSuggestion } from "../api/analyzeProblems";

export default function ProblemsPage() {
  const { selectedProject, selectedProjectId, loading: projectLoading } = useProject();
  const [problems, setProblems] = useState<Problem[]>([]);
  const [loadingProblems, setLoadingProblems] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [aiSuggestions, setAiSuggestions] = useState<Record<string, string>>({});
  const [loadingSuggestions, setLoadingSuggestions] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (!selectedProjectId) return;
    setLoadingProblems(true);
    getProblemsByProject(selectedProjectId)
      .then((data) => setProblems(data))
      .finally(() => setLoadingProblems(false));
  }, [selectedProjectId]);

  const onAnalyze = async () => {
    if (!selectedProject || !selectedProjectId) return;
    setAnalyzing(true);
    try {
      await analyzeProblems({ projectId: selectedProjectId!, targetKeyword: selectedProject.project.targetKeyword, queries: selectedProject.queries, metrics: selectedProject.metrics });
      const data = await getProblemsByProject(selectedProjectId);
      setProblems(data);
    } finally {
      setAnalyzing(false);
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const onGetAISuggestion = async (problemId: string) => {
    if (aiSuggestions[problemId]) {
      toggleExpand(problemId);
      return;
    }
    setLoadingSuggestions((prev) => new Set(prev).add(problemId));
    try {
      const prob = problems.find(p => p.id === problemId);
      const suggestion = prob ? await getAIProblemSuggestion({ title: prob.title, summary: prob.summary ?? "", problemType: prob.problemType }, selectedProject!.project.targetKeyword) : "";
      setAiSuggestions((prev) => ({ ...prev, [problemId]: suggestion }));
      setExpandedIds((prev) => new Set(prev).add(problemId));
    } finally {
      setLoadingSuggestions((prev) => {
        const next = new Set(prev);
        next.delete(problemId);
        return next;
      });
    }
  };

  const onUpdateStatus = async (problemId: string, status: "active" | "improving" | "resolved" | "ignored") => {
    await updateProblem(selectedProjectId!, problemId, { status });
    setProblems((prev) =>
      prev.map((p) => (p.id === problemId ? { ...p, status } : p)) as Problem[]
    );
  };

  const severityConfig: Record<string, { label: string; bg: string; text: string }> = {
    critical: { label: "심각", bg: "bg-red-100", text: "text-red-700" },
    high: { label: "높음", bg: "bg-orange-100", text: "text-orange-700" },
    medium: { label: "중간", bg: "bg-yellow-100", text: "text-yellow-700" },
    low: { label: "낮음", bg: "bg-blue-100", text: "text-blue-700" },
  };

  const statusConfig: Record<string, { label: string; bg: string; text: string }> = {
    active: { label: "활성", bg: "bg-slate-100", text: "text-slate-600" },
    improving: { label: "개선 중", bg: "bg-blue-100", text: "text-blue-600" },
    resolved: { label: "해결됨", bg: "bg-green-100", text: "text-green-700" },
    ignored: { label: "무시됨", bg: "bg-gray-100", text: "text-gray-500" },
  };

  const severityCounts = {
    critical: problems.filter((p) => p.severity === "critical").length,
    high: problems.filter((p) => p.severity === "high").length,
    medium: problems.filter((p) => p.severity === "medium").length,
    low: problems.filter((p) => p.severity === "low").length,
  };

  if (projectLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!selectedProject) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-slate-500 text-sm">프로젝트를 먼저 선택하세요.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Problems</h1>
          <p className="text-sm text-slate-500 mt-1">{selectedProject.project.name}</p>
        </div>
        <button
          onClick={onAnalyze}
          disabled={analyzing}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 disabled:opacity-60 transition-colors"
        >
          {analyzing ? (
            <RefreshCw className="w-4 h-4 animate-spin" />
          ) : (
            <AlertCircle className="w-4 h-4" />
          )}
          문제 분석 실행
        </button>
      </div>

      {problems.length > 0 && (
        <div className="flex gap-3 mb-6">
          {Object.entries(severityCounts).map(([key, count]) => {
            const cfg = severityConfig[key];
            return (
              <span
                key={key}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium ${cfg.bg} ${cfg.text}`}
              >
                {cfg.label}
                <span className="font-bold">{count}</span>
              </span>
            );
          })}
        </div>
      )}

      {loadingProblems ? (
        <div className="flex items-center justify-center h-48">
          <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
        </div>
      ) : problems.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-64 bg-white rounded-xl border border-slate-200">
          <AlertCircle className="w-10 h-10 text-slate-300 mb-3" />
          <p className="text-slate-400 text-sm mb-4">발견된 문제가 없습니다.</p>
          <button
            onClick={onAnalyze}
            disabled={analyzing}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 disabled:opacity-60 transition-colors"
          >
            {analyzing ? (
              <RefreshCw className="w-4 h-4 animate-spin" />
            ) : (
              <AlertCircle className="w-4 h-4" />
            )}
            문제 분석 실행
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {problems.map((problem) => {
            const sevCfg = severityConfig[problem.severity] ?? severityConfig.low;
            const stCfg = statusConfig[problem.status] ?? statusConfig.active;
            const isExpanded = expandedIds.has(problem.id ?? "");
            const suggestion = aiSuggestions[problem.id ?? ""];
            const loadingSuggestion = loadingSuggestions.has(problem.id ?? "");

            return (
              <div
                key={problem.id}
                className="bg-white rounded-xl border border-slate-200 p-4"
              >
                <div className="flex items-start justify-between gap-3 mb-2">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span
                      className={`px-2 py-0.5 rounded-full text-xs font-medium ${sevCfg.bg} ${sevCfg.text}`}
                    >
                      {sevCfg.label}
                    </span>
                    {problem.score !== undefined && (
                      <span className="px-2 py-0.5 bg-slate-100 text-slate-600 text-xs rounded-full font-medium">
                        {problem.score}점
                      </span>
                    )}
                    <span
                      className={`px-2 py-0.5 rounded-full text-xs font-medium ${stCfg.bg} ${stCfg.text}`}
                    >
                      {stCfg.label}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <button
                      onClick={() => onUpdateStatus(problem.id ?? "", "ignored")}
                      className="px-2.5 py-1 text-xs text-slate-500 border border-slate-200 rounded-lg hover:bg-slate-50 transition-colors"
                    >
                      무시
                    </button>
                    <button
                      onClick={() => onUpdateStatus(problem.id ?? "", "resolved")}
                      className="flex items-center gap-1 px-2.5 py-1 text-xs text-green-600 border border-green-200 rounded-lg hover:bg-green-50 transition-colors"
                    >
                      <CheckCircle className="w-3 h-3" />
                      해결됨
                    </button>
                  </div>
                </div>

                <h3 className="text-sm font-semibold text-slate-800 mb-1">{problem.title}</h3>
                <p className="text-sm text-slate-500 line-clamp-2">{problem.summary}</p>

                <div className="mt-3">
                  <button
                    onClick={() => onGetAISuggestion(problem.id ?? "")}
                    disabled={loadingSuggestion}
                    className="flex items-center gap-1 text-xs text-blue-600 hover:text-blue-700 font-medium"
                  >
                    {loadingSuggestion ? (
                      <RefreshCw className="w-3 h-3 animate-spin" />
                    ) : isExpanded && suggestion ? (
                      <ChevronUp className="w-3 h-3" />
                    ) : (
                      <ChevronDown className="w-3 h-3" />
                    )}
                    AI 전략 보기
                  </button>

                  {isExpanded && suggestion && (
                    <div className="mt-2 p-3 bg-blue-50 rounded-lg text-sm text-slate-700 border border-blue-100">
                      {suggestion}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
