import { useState } from "react";
import { RefreshCw } from "lucide-react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import { useProject } from "../contexts/ProjectContext";

const CLUSTERS = ["지역", "속성", "비교", "추천", "미분류"];

export default function PerformancePage() {
  const { selectedProject, loading } = useProject();
  const [_] = useState(null);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!selectedProject) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-slate-500 text-sm">프로젝트를 먼저 선택하세요.</p>
      </div>
    );
  }

  const { metrics, queries } = selectedProject;

  const totalQueries = queries.length;
  const totalMetrics = metrics.length;

  const mentionCount = metrics.filter((m) => m.mention).length;
  const mentionRate =
    totalMetrics > 0 ? Math.round((mentionCount / totalMetrics) * 100) : 0;

  const recommendCount = metrics.filter((m) => m.isRecommended).length;
  const recommendRate =
    totalMetrics > 0 ? Math.round((recommendCount / totalMetrics) * 100) : 0;

  const avgScore =
    totalMetrics > 0
      ? Math.round(metrics.reduce((sum, m) => sum + (m.score ?? 0), 0) / totalMetrics)
      : 0;

  const clusterChartData = CLUSTERS.map((cluster) => {
    const clusterQueryIds = queries
      .filter((q) => (q.cluster ?? "미분류") === cluster)
      .map((q) => q.id);
    const clusterMetrics = metrics.filter((m) => clusterQueryIds.includes(m.queryId));
    const avg =
      clusterMetrics.length > 0
        ? Math.round(
            clusterMetrics.reduce((sum, m) => sum + (m.score ?? 0), 0) /
              clusterMetrics.length
          )
        : 0;
    return { cluster, avg };
  });

  const competitorMap: Record<string, number> = {};
  metrics.forEach((m) => {
    if (Array.isArray(m.competitors)) {
      m.competitors.forEach((c: string) => {
        competitorMap[c] = (competitorMap[c] ?? 0) + 1;
      });
    }
  });
  const competitorList = Object.entries(competitorMap)
    .sort((a, b) => b[1] - a[1])
    .map(([name, count]) => ({
      name,
      count,
      pct: totalMetrics > 0 ? Math.round((count / totalMetrics) * 100) : 0,
    }));

  const scoredQueries = queries
    .map((q) => {
      const qMetrics = metrics.filter((m) => m.queryId === q.id);
      const avg =
        qMetrics.length > 0
          ? Math.round(
              qMetrics.reduce((sum, m) => sum + (m.score ?? 0), 0) / qMetrics.length
            )
          : 0;
      return { id: q.id, text: q.text, avg };
    })
    .filter((q) => q.avg > 0)
    .sort((a, b) => b.avg - a.avg);

  const top5 = scoredQueries.slice(0, 5);
  const bottom5 = [...scoredQueries].reverse().slice(0, 5);

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800">Performance</h1>
        <p className="text-sm text-slate-500 mt-1">{selectedProject.project.name}</p>
      </div>

      <div className="grid grid-cols-4 gap-4 mb-8">
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <p className="text-xs text-slate-500 mb-1">언급률</p>
          <p className="text-2xl font-bold text-blue-600">{mentionRate}%</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <p className="text-xs text-slate-500 mb-1">추천 포함률</p>
          <p className="text-2xl font-bold text-green-600">{recommendRate}%</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <p className="text-xs text-slate-500 mb-1">평균 점수</p>
          <p className="text-2xl font-bold text-slate-800">{avgScore}</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <p className="text-xs text-slate-500 mb-1">총 쿼리</p>
          <p className="text-2xl font-bold text-slate-800">{totalQueries}</p>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-slate-200 p-5 mb-6">
        <h2 className="text-sm font-semibold text-slate-700 mb-4">클러스터별 평균 점수</h2>
        <ResponsiveContainer width="100%" height={220}>
          <BarChart data={clusterChartData} barSize={36}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
            <XAxis
              dataKey="cluster"
              tick={{ fontSize: 12, fill: "#64748b" }}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              domain={[0, 100]}
              tick={{ fontSize: 12, fill: "#64748b" }}
              axisLine={false}
              tickLine={false}
            />
            <Tooltip
              contentStyle={{
                borderRadius: "8px",
                border: "1px solid #e2e8f0",
                fontSize: "12px",
              }}
              formatter={(value: number) => [`${value}점`, "평균 점수"]}
            />
            <Bar dataKey="avg" fill="#2563eb" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-2 gap-6 mb-6">
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <h2 className="text-sm font-semibold text-slate-700 mb-3">상위 5 쿼리</h2>
          {top5.length === 0 ? (
            <p className="text-xs text-slate-400">데이터 없음</p>
          ) : (
            <div className="space-y-2">
              {top5.map((q, i) => (
                <div key={q.id} className="flex items-center gap-2">
                  <span className="text-xs text-slate-400 w-4 shrink-0">{i + 1}</span>
                  <p className="text-xs text-slate-600 flex-1 truncate">{q.text}</p>
                  <span className="text-xs font-semibold text-blue-600 shrink-0">
                    {q.avg}점
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <h2 className="text-sm font-semibold text-slate-700 mb-3">하위 5 쿼리</h2>
          {bottom5.length === 0 ? (
            <p className="text-xs text-slate-400">데이터 없음</p>
          ) : (
            <div className="space-y-2">
              {bottom5.map((q, i) => (
                <div key={q.id} className="flex items-center gap-2">
                  <span className="text-xs text-slate-400 w-4 shrink-0">{i + 1}</span>
                  <p className="text-xs text-slate-600 flex-1 truncate">{q.text}</p>
                  <span className="text-xs font-semibold text-red-500 shrink-0">
                    {q.avg}점
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {competitorList.length > 0 && (
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <h2 className="text-sm font-semibold text-slate-700 mb-3">경쟁사 언급 빈도</h2>
          <div className="space-y-2">
            {competitorList.map((c) => (
              <div key={c.name} className="flex items-center gap-3">
                <p className="text-sm text-slate-700 w-40 truncate">{c.name}</p>
                <div className="flex-1 bg-slate-100 rounded-full h-2">
                  <div
                    className="bg-blue-500 h-2 rounded-full"
                    style={{ width: `${c.pct}%` }}
                  />
                </div>
                <span className="text-xs text-slate-500 w-16 text-right">
                  {c.count}회 ({c.pct}%)
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
