import { useState, useEffect } from 'react';
import { Database, AlertTriangle, CheckCircle, XCircle, RefreshCw, Trash2, ChevronDown, ChevronUp } from 'lucide-react';
import {
  runMigration,
  getLegacyCollectionCounts,
  deleteLegacyCollection,
  type MigrationResult,
  type CollectionMigrationResult
} from '../db/migration';

const COL_LABEL: Record<string, string> = {
  QUERIES: 'jkai011_queries',
  ANSWERS: 'jkai011_answers',
  METRICS: 'jkai011_metrics',
  CONTENTS: 'jkai011_contents'
};

function CollectionRow({ result }: { result: CollectionMigrationResult }) {
  const hasErrors = result.errors > 0;

  return (
    <div className="flex items-center justify-between py-2 px-4 rounded-lg bg-slate-50 text-sm">
      <span className="font-mono text-slate-700">{result.collection}</span>
      <div className="flex gap-4 text-xs">
        <span className="text-slate-500">전체 <b className="text-slate-700">{result.total}</b></span>
        <span className="text-green-600">이동 <b>{result.migrated}</b></span>
        <span className="text-slate-400">스킵 <b>{result.skipped}</b></span>
        {hasErrors && <span className="text-red-500">오류 <b>{result.errors}</b></span>}
      </div>
    </div>
  );
}

function DeleteSection({
  counts,
  onDeleted
}: {
  counts: Record<string, number>;
  onDeleted: () => void;
}) {
  const [deleting, setDeleting] = useState<string | null>(null);
  const [deleted, setDeleted] = useState<Record<string, number>>({});
  const [expanded, setExpanded] = useState(false);

  const totalLegacyDocs = Object.values(counts).reduce((a, b) => a + (b > 0 ? b : 0), 0);

  if (totalLegacyDocs === 0) {
    return (
      <div className="mt-6 p-4 rounded-lg bg-green-50 border border-green-200 flex items-center gap-2 text-green-700 text-sm">
        <CheckCircle className="w-4 h-4 flex-shrink-0" />
        레거시 컬렉션이 비어 있습니다. 정리가 필요하지 않습니다.
      </div>
    );
  }

  const handleDelete = async (key: string, name: string) => {
    if (!window.confirm(`"${name}" 컬렉션의 모든 문서(${counts[key]}개)를 삭제하시겠습니까?\n\n이 작업은 되돌릴 수 없습니다.`)) return;
    setDeleting(key);
    try {
      const count = await deleteLegacyCollection(name);
      setDeleted(prev => ({ ...prev, [key]: count }));
      onDeleted();
    } catch (err) {
      alert(`삭제 실패: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setDeleting(null);
    }
  };

  return (
    <div className="mt-6 border border-orange-200 rounded-lg overflow-hidden">
      <button
        onClick={() => setExpanded(!expanded)}
        className="flex items-center justify-between w-full px-4 py-3 bg-orange-50 text-orange-800 text-sm font-medium hover:bg-orange-100 transition-colors"
      >
        <div className="flex items-center gap-2">
          <Trash2 className="w-4 h-4" />
          레거시 컬렉션 수동 삭제 ({totalLegacyDocs}개 문서 잔여)
        </div>
        {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
      </button>

      {expanded && (
        <div className="p-4 space-y-2 bg-white">
          <p className="text-xs text-slate-500 mb-3">
            마이그레이션 완료 후 기존 루트 컬렉션 데이터를 삭제할 수 있습니다.
            삭제 전 마이그레이션이 정상적으로 완료되었는지 반드시 확인하세요.
          </p>
          {Object.entries(COL_LABEL).map(([key, name]) => {
            const count = counts[key] ?? 0;
            const isDeleted = deleted[key] !== undefined;

            return (
              <div key={key} className="flex items-center justify-between py-2 px-3 rounded border border-slate-200 text-sm">
                <div>
                  <span className="font-mono text-slate-700">{name}</span>
                  <span className="ml-2 text-slate-400 text-xs">
                    {isDeleted ? `${deleted[key]}개 삭제됨` : `${count >= 0 ? count : '?'}개`}
                  </span>
                </div>
                <button
                  onClick={() => handleDelete(key, name)}
                  disabled={deleting !== null || count === 0 || isDeleted}
                  className="flex items-center gap-1 px-3 py-1 rounded text-xs font-medium bg-red-50 text-red-600 hover:bg-red-100 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  {deleting === key ? (
                    <RefreshCw className="w-3 h-3 animate-spin" />
                  ) : isDeleted ? (
                    <CheckCircle className="w-3 h-3" />
                  ) : (
                    <Trash2 className="w-3 h-3" />
                  )}
                  {isDeleted ? '삭제됨' : '삭제'}
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default function MigrationPage() {
  const [migrationResult, setMigrationResult] = useState<MigrationResult | null>(null);
  const [legacyCounts, setLegacyCounts] = useState<Record<string, number> | null>(null);
  const [loadingCounts, setLoadingCounts] = useState(true);
  const [running, setRunning] = useState(false);

  const loadCounts = async () => {
    setLoadingCounts(true);
    try {
      const counts = await getLegacyCollectionCounts();
      setLegacyCounts(counts);
    } catch {
      setLegacyCounts({});
    } finally {
      setLoadingCounts(false);
    }
  };

  useEffect(() => {
    loadCounts();
  }, []);

  const handleRun = async () => {
    setRunning(true);
    setMigrationResult(null);

    await runMigration((progress) => {
      setMigrationResult({ ...progress });
    });

    setRunning(false);
    loadCounts();
  };

  const totalLegacy = legacyCounts
    ? Object.values(legacyCounts).reduce((a, b) => a + (b > 0 ? b : 0), 0)
    : 0;

  const statusIcon = migrationResult?.status === 'done'
    ? <CheckCircle className="w-5 h-5 text-green-500" />
    : migrationResult?.status === 'error'
    ? <XCircle className="w-5 h-5 text-red-500" />
    : migrationResult?.status === 'running'
    ? <RefreshCw className="w-5 h-5 text-blue-500 animate-spin" />
    : null;

  return (
    <div className="p-6 lg:p-8 max-w-3xl mx-auto">
      <div className="flex items-center gap-3 mb-2">
        <Database className="w-6 h-6 text-slate-600" />
        <h1 className="text-2xl font-bold text-slate-900">Migration</h1>
        <span className="ml-1 px-2 py-0.5 rounded text-xs font-semibold bg-amber-100 text-amber-700 uppercase tracking-wide">Dev Only</span>
      </div>
      <p className="text-slate-500 text-sm mb-8">
        기존 루트 컬렉션 데이터를 프로젝트 서브컬렉션 구조로 이동합니다.
      </p>

      <div className="bg-white rounded-xl border border-slate-200 p-6 mb-6">
        <h2 className="text-sm font-semibold text-slate-700 mb-4">레거시 컬렉션 현황</h2>

        {loadingCounts ? (
          <div className="flex items-center gap-2 text-slate-400 text-sm py-2">
            <RefreshCw className="w-4 h-4 animate-spin" />
            조회 중...
          </div>
        ) : (
          <div className="space-y-2">
            {Object.entries(COL_LABEL).map(([key, name]) => {
              const count = legacyCounts?.[key] ?? 0;
              return (
                <div key={key} className="flex items-center justify-between py-2 px-4 rounded-lg bg-slate-50 text-sm">
                  <span className="font-mono text-slate-700">{name}</span>
                  <span className={`font-semibold ${count > 0 ? 'text-orange-600' : 'text-slate-400'}`}>
                    {count >= 0 ? `${count}개` : '조회 오류'}
                  </span>
                </div>
              );
            })}

            <div className="flex items-center justify-between pt-2 px-4 text-sm font-semibold">
              <span className="text-slate-600">합계</span>
              <span className={totalLegacy > 0 ? 'text-orange-600' : 'text-green-600'}>
                {totalLegacy}개
              </span>
            </div>
          </div>
        )}
      </div>

      {totalLegacy > 0 && !migrationResult && (
        <div className="flex items-start gap-3 p-4 rounded-lg bg-amber-50 border border-amber-200 mb-6 text-sm text-amber-800">
          <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0" />
          <div>
            <b>마이그레이션 전 확인사항</b>
            <ul className="mt-1 space-y-0.5 list-disc list-inside text-amber-700">
              <li>마이그레이션은 기존 루트 컬렉션 데이터를 <b>복사</b>합니다 (삭제 안 함)</li>
              <li>이미 서브컬렉션에 데이터가 있으면 중복 생성될 수 있습니다</li>
              <li>마이그레이션 완료 후 레거시 데이터를 직접 삭제하세요</li>
            </ul>
          </div>
        </div>
      )}

      <button
        onClick={handleRun}
        disabled={running || totalLegacy === 0}
        className="flex items-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors disabled:bg-slate-300 disabled:cursor-not-allowed text-sm mb-6"
      >
        {running ? (
          <><RefreshCw className="w-4 h-4 animate-spin" /> 마이그레이션 실행 중...</>
        ) : (
          <><Database className="w-4 h-4" /> 마이그레이션 실행</>
        )}
      </button>

      {migrationResult && (
        <div className="bg-white rounded-xl border border-slate-200 p-6 mb-6">
          <div className="flex items-center gap-2 mb-4">
            {statusIcon}
            <h2 className="text-sm font-semibold text-slate-700">
              {migrationResult.status === 'done' && '마이그레이션 완료'}
              {migrationResult.status === 'error' && '마이그레이션 오류'}
              {migrationResult.status === 'running' && '마이그레이션 진행 중...'}
            </h2>
            {migrationResult.finishedAt && migrationResult.startedAt && (
              <span className="ml-auto text-xs text-slate-400">
                {((migrationResult.finishedAt.getTime() - migrationResult.startedAt.getTime()) / 1000).toFixed(1)}초
              </span>
            )}
          </div>

          {migrationResult.errorMessage && (
            <div className="mb-4 p-3 rounded-lg bg-red-50 text-red-700 text-sm">
              {migrationResult.errorMessage}
            </div>
          )}

          <div className="space-y-2">
            {migrationResult.collections.map((col) => (
              <CollectionRow key={col.collection} result={col} />
            ))}
          </div>

          {migrationResult.collections.length > 0 && (
            <div className="mt-4 pt-4 border-t border-slate-100 flex gap-6 text-xs text-slate-500">
              <span>총 이동: <b className="text-green-600">{migrationResult.collections.reduce((a, c) => a + c.migrated, 0)}</b></span>
              <span>스킵: <b>{migrationResult.collections.reduce((a, c) => a + c.skipped, 0)}</b></span>
              <span>오류: <b className="text-red-500">{migrationResult.collections.reduce((a, c) => a + c.errors, 0)}</b></span>
            </div>
          )}
        </div>
      )}

      {legacyCounts && (
        <DeleteSection counts={legacyCounts} onDeleted={loadCounts} />
      )}
    </div>
  );
}
