import { useState } from 'react';
import { MessageSquare, Plus, RefreshCw, Tag, MapPin, ChevronDown, ChevronUp, Zap } from 'lucide-react';
import { useProject } from '../contexts/ProjectContext';
import { createQuery } from '../db/firestore';
import { handleGenerateQueries } from '../api/generateQueries';
import { classifyQueriesWithAI, applyQueryClassifications } from '../api/classifyQueries';

const CLUSTER_LABELS: Record<string, { label: string; color: string }> = {
  region_extension: { label: '지역', color: 'bg-blue-100 text-blue-700' },
  attribute_focused: { label: '속성', color: 'bg-green-100 text-green-700' },
  comparison: { label: '비교', color: 'bg-orange-100 text-orange-700' },
  recommendation: { label: '추천', color: 'bg-rose-100 text-rose-700' }
};

const INTENT_LABELS: Record<string, string> = {
  recommendation: '추천',
  comparison: '비교',
  information: '정보'
};

export default function QueriesPage() {
  const { selectedProject, selectedProjectId, loading, reload } = useProject();
  const [generating, setGenerating] = useState(false);
  const [classifying, setClassifying] = useState(false);
  const [addingManual, setAddingManual] = useState(false);
  const [manualText, setManualText] = useState('');
  const [status, setStatus] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const queries = selectedProject?.queries ?? [];

  const handleGenerate = async () => {
    if (!selectedProjectId || !selectedProject) return;
    setGenerating(true);
    setStatus('AI로 질문 생성 중...');
    try {
      const result = await handleGenerateQueries({
        keyword: selectedProject.project.targetKeyword,
        projectId: selectedProjectId
      });
      if (result.success) {
        setStatus(`${result.queries.length}개 질문이 생성되었습니다.`);
        await reload();
      } else {
        setStatus(`오류: ${result.error}`);
      }
    } finally {
      setGenerating(false);
      setTimeout(() => setStatus(''), 3000);
    }
  };

  const handleClassify = async () => {
    if (!selectedProjectId || queries.length === 0) return;
    setClassifying(true);
    setStatus('질문 분류 중...');
    try {
      const input = queries.map(q => ({ id: q.id!, text: q.text }));
      const classifications = await classifyQueriesWithAI(input);
      await applyQueryClassifications(selectedProjectId, classifications);
      setStatus(`${classifications.length}개 질문이 분류되었습니다.`);
      await reload();
    } catch (err) {
      setStatus(`분류 오류: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setClassifying(false);
      setTimeout(() => setStatus(''), 3000);
    }
  };

  const handleAddManual = async () => {
    if (!selectedProjectId || !manualText.trim()) return;
    try {
      await createQuery(selectedProjectId, { text: manualText.trim() });
      setManualText('');
      setAddingManual(false);
      await reload();
    } catch (err) {
      setStatus(`오류: ${err instanceof Error ? err.message : String(err)}`);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-64">
        <RefreshCw className="w-6 h-6 animate-spin text-slate-400" />
      </div>
    );
  }

  if (!selectedProject) {
    return (
      <div className="p-8 text-center text-slate-500">
        <MessageSquare className="w-12 h-12 mx-auto mb-3 text-slate-300" />
        <p>프로젝트를 먼저 선택하세요.</p>
      </div>
    );
  }

  const clustered = Object.entries(
    queries.reduce<Record<string, typeof queries>>((acc, q) => {
      const key = q.cluster || 'unclassified';
      if (!acc[key]) acc[key] = [];
      acc[key].push(q);
      return acc;
    }, {})
  );

  return (
    <div className="p-6 lg:p-8 max-w-5xl mx-auto">
      <div className="flex items-start justify-between mb-2">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Queries</h1>
          <p className="text-sm text-slate-500 mt-1">
            {selectedProject.project.name} · {queries.length}개 질문
          </p>
        </div>
        <div className="flex gap-2">
          {queries.length > 0 && (
            <button
              onClick={handleClassify}
              disabled={classifying}
              className="flex items-center gap-1.5 px-3 py-2 text-sm border border-slate-300 rounded-lg hover:bg-slate-50 disabled:opacity-50 transition-colors"
            >
              {classifying ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Tag className="w-4 h-4" />}
              분류
            </button>
          )}
          <button
            onClick={() => setAddingManual(v => !v)}
            className="flex items-center gap-1.5 px-3 py-2 text-sm border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors"
          >
            <Plus className="w-4 h-4" />
            직접 추가
          </button>
          <button
            onClick={handleGenerate}
            disabled={generating}
            className="flex items-center gap-1.5 px-4 py-2 text-sm bg-blue-600 hover:bg-blue-700 text-white rounded-lg disabled:opacity-50 transition-colors"
          >
            {generating ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
            AI 생성
          </button>
        </div>
      </div>

      {status && (
        <div className="mt-3 px-4 py-2 rounded-lg bg-blue-50 text-blue-700 text-sm">
          {status}
        </div>
      )}

      {addingManual && (
        <div className="mt-4 p-4 bg-white rounded-xl border border-slate-200 flex gap-2">
          <input
            type="text"
            value={manualText}
            onChange={e => setManualText(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleAddManual()}
            placeholder="질문을 직접 입력하세요"
            className="flex-1 px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            autoFocus
          />
          <button
            onClick={handleAddManual}
            disabled={!manualText.trim()}
            className="px-4 py-2 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700 disabled:opacity-40 transition-colors"
          >
            추가
          </button>
          <button
            onClick={() => setAddingManual(false)}
            className="px-3 py-2 border border-slate-300 text-slate-600 text-sm rounded-lg hover:bg-slate-50 transition-colors"
          >
            취소
          </button>
        </div>
      )}

      {queries.length === 0 ? (
        <div className="mt-8 bg-white rounded-xl border border-slate-200 p-12 text-center">
          <MessageSquare className="w-12 h-12 mx-auto mb-4 text-slate-300" />
          <h3 className="text-lg font-semibold text-slate-700 mb-2">질문이 없습니다</h3>
          <p className="text-slate-500 text-sm mb-6">AI 생성 버튼으로 키워드 기반 질문을 자동 생성하세요.</p>
          <button
            onClick={handleGenerate}
            disabled={generating}
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors text-sm font-medium"
          >
            {generating ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
            AI로 질문 생성
          </button>
        </div>
      ) : (
        <div className="mt-6 space-y-4">
          {clustered.map(([cluster, clusterQueries]) => {
            const clusterInfo = CLUSTER_LABELS[cluster];
            return (
              <div key={cluster} className="bg-white rounded-xl border border-slate-200 overflow-hidden">
                <div className="px-5 py-3 border-b border-slate-100 flex items-center gap-2">
                  {clusterInfo ? (
                    <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${clusterInfo.color}`}>
                      {clusterInfo.label}
                    </span>
                  ) : (
                    <span className="text-xs px-2 py-0.5 rounded-full font-medium bg-slate-100 text-slate-500">
                      미분류
                    </span>
                  )}
                  <span className="text-sm text-slate-400">{clusterQueries.length}개</span>
                </div>
                <div className="divide-y divide-slate-50">
                  {clusterQueries.map(q => (
                    <div key={q.id} className="px-5 py-3">
                      <div
                        className="flex items-start justify-between cursor-pointer"
                        onClick={() => setExpandedId(expandedId === q.id ? null : q.id!)}
                      >
                        <p className="text-sm text-slate-800 flex-1 pr-4">{q.text}</p>
                        <div className="flex items-center gap-2 flex-shrink-0">
                          {q.intent && (
                            <span className="text-xs text-slate-400">{INTENT_LABELS[q.intent] ?? q.intent}</span>
                          )}
                          {q.importanceWeight !== undefined && (
                            <span className="text-xs font-mono text-slate-400">
                              {q.importanceWeight.toFixed(1)}
                            </span>
                          )}
                          {expandedId === q.id
                            ? <ChevronUp className="w-4 h-4 text-slate-300" />
                            : <ChevronDown className="w-4 h-4 text-slate-300" />
                          }
                        </div>
                      </div>
                      {expandedId === q.id && (
                        <div className="mt-2 flex flex-wrap gap-2">
                          {q.regionPrimary && (
                            <span className="flex items-center gap-1 text-xs text-slate-500 bg-slate-50 px-2 py-1 rounded">
                              <MapPin className="w-3 h-3" />
                              {q.regionPrimary}
                              {q.regionSecondary && ` · ${q.regionSecondary}`}
                            </span>
                          )}
                          {q.status && (
                            <span className={`text-xs px-2 py-1 rounded ${q.status === 'active' ? 'bg-green-50 text-green-600' : 'bg-slate-50 text-slate-400'}`}>
                              {q.status === 'active' ? '활성' : '비활성'}
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
