import { askLLM } from '../services/openai';
import { updateDoc, doc } from 'firebase/firestore';
import { db } from '../config/firebase';
import { COLLECTIONS, SUB_COLLECTIONS } from '../db/firestore';

export interface QueryClassification {
  queryId: string;
  cluster: 'region_extension' | 'attribute_focused' | 'comparison' | 'recommendation';
  intent: 'recommendation' | 'comparison' | 'information';
  regionPrimary?: string;
  regionSecondary?: string;
  importanceWeight: number;
}

export async function classifyQueriesWithAI(
  queries: { id: string; text: string }[]
): Promise<QueryClassification[]> {
  const queryList = queries.map((q, i) => `${i + 1}. [${q.id}] ${q.text}`).join('\n');

  const prompt = `다음 질문 목록을 분석하여 각 질문의 분류 정보를 JSON 배열로 반환해주세요.

질문 목록:
${queryList}

각 항목에 대해 다음 정보를 추출하세요:
- queryId: 질문 ID (대괄호 안의 값)
- cluster: 다음 중 하나 선택
  - "region_extension": 지역 확장 관련 질문 (특정 지역 언급)
  - "attribute_focused": 속성/특징 관련 질문 (특정 기능, 특성 문의)
  - "comparison": 비교 관련 질문 (vs, 차이, 비교)
  - "recommendation": 추천 관련 질문 (추천, 어디가 좋은지, 어디로 가야 하는지)
- intent: 다음 중 하나 선택
  - "recommendation": 추천을 원함
  - "comparison": 비교를 원함
  - "information": 정보를 원함
- regionPrimary: 질문에서 언급된 주요 지역 (없으면 null)
- regionSecondary: 질문에서 언급된 보조 지역 (없으면 null)
- importanceWeight: 0.1~1.0 사이의 중요도 (추천/비교 질문은 높게, 정보성은 낮게)

반드시 JSON 배열만 반환하세요. 다른 텍스트 없이.
예시: [{"queryId":"abc123","cluster":"recommendation","intent":"recommendation","regionPrimary":"강남","regionSecondary":null,"importanceWeight":0.9}]`;

  const response = await askLLM(prompt);

  const jsonMatch = response.match(/\[[\s\S]*\]/);
  if (!jsonMatch) {
    throw new Error('AI 응답에서 JSON을 파싱할 수 없습니다');
  }

  return JSON.parse(jsonMatch[0]) as QueryClassification[];
}

export async function applyQueryClassifications(
  projectId: string,
  classifications: QueryClassification[]
): Promise<void> {
  for (const cls of classifications) {
    const docRef = doc(db, COLLECTIONS.PROJECTS, projectId, SUB_COLLECTIONS.QUERIES, cls.queryId);
    const updates: Record<string, any> = {
      cluster: cls.cluster,
      intent: cls.intent,
      importanceWeight: cls.importanceWeight
    };
    if (cls.regionPrimary) updates.regionPrimary = cls.regionPrimary;
    if (cls.regionSecondary) updates.regionSecondary = cls.regionSecondary;

    await updateDoc(docRef, updates);
  }
}
