import { useState } from 'react';
import { FolderOpen, MessageSquare, AlertCircle, Play, TrendingUp, Zap, LogOut, Menu, X, ChevronDown, ChevronRight, Database } from 'lucide-react';
import { signOut } from 'firebase/auth';
import { auth } from '../config/firebase';
import { useProject } from '../contexts/ProjectContext';

const IS_DEV = import.meta.env.DEV;

interface NavigationProps {
  currentPage: string;
  onNavigate: (page: string) => void;
  user: any;
}

const topMenuItems = [
  { id: 'projects', label: 'Projects', icon: FolderOpen },
];

const menuGroups = [
  {
    label: '데이터 수집',
    items: [
      { id: 'queries', label: 'Queries', icon: MessageSquare },
      { id: 'ai-answers', label: 'AI Answers', icon: MessageSquare },
    ],
  },
  {
    label: '문제 해결',
    items: [
      { id: 'problems', label: 'Problems', icon: AlertCircle },
      { id: 'actions', label: 'Actions', icon: Play },
    ],
  },
  {
    label: '측정 / 자동화',
    items: [
      { id: 'performance', label: 'Performance', icon: TrendingUp },
      { id: 'automation', label: 'Automation', icon: Zap },
    ],
  },
];

export default function Navigation({ currentPage, onNavigate, user }: NavigationProps) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isProjectDropdownOpen, setIsProjectDropdownOpen] = useState(false);
  const { projects, selectedProjectId, selectedProject, setSelectedProjectId, loading } = useProject();

  const handleSignOut = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error('Sign out error:', error);
    }
  };

  const handleSelectProject = (id: string) => {
    setSelectedProjectId(id);
    setIsProjectDropdownOpen(false);
    if (currentPage === 'projects') {
      onNavigate('queries');
    }
  };

  const handleNavigate = (page: string) => {
    onNavigate(page);
    setIsMobileMenuOpen(false);
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full">
      <div className="flex items-center h-16 px-6 border-b border-gray-200 flex-shrink-0">
        <h1 className="text-xl font-bold text-gray-900">GEO Insight</h1>
      </div>

      <div className="px-3 py-3 border-b border-gray-100 flex-shrink-0">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider px-3 mb-2">현재 프로젝트</p>
        {loading ? (
          <div className="px-3 py-2 text-sm text-gray-400">로딩 중...</div>
        ) : projects.length === 0 ? (
          <button
            onClick={() => handleNavigate('projects')}
            className="flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm text-gray-500 hover:bg-gray-50 transition-colors"
          >
            <FolderOpen className="w-4 h-4" />
            <span>프로젝트 없음</span>
          </button>
        ) : (
          <div className="relative">
            <button
              onClick={() => setIsProjectDropdownOpen(!isProjectDropdownOpen)}
              className="flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm font-medium text-gray-800 hover:bg-gray-50 transition-colors group"
            >
              <div className="w-2 h-2 rounded-full bg-green-500 flex-shrink-0" />
              <span className="flex-1 text-left truncate">
                {selectedProject?.project.name || '프로젝트 선택'}
              </span>
              <ChevronDown className={`w-4 h-4 text-gray-400 transition-transform flex-shrink-0 ${isProjectDropdownOpen ? 'rotate-180' : ''}`} />
            </button>
            {selectedProject && (
              <p className="text-xs text-gray-400 px-3 mt-0.5 truncate">
                {selectedProject.project.targetKeyword}
              </p>
            )}
            {isProjectDropdownOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-50 overflow-hidden">
                {projects.map(({ project }) => (
                  <button
                    key={project.id}
                    onClick={() => handleSelectProject(project.id!)}
                    className={`flex items-center gap-2 w-full px-3 py-2.5 text-sm text-left hover:bg-gray-50 transition-colors ${
                      project.id === selectedProjectId ? 'bg-blue-50 text-blue-700' : 'text-gray-700'
                    }`}
                  >
                    <div className={`w-2 h-2 rounded-full flex-shrink-0 ${project.id === selectedProjectId ? 'bg-blue-500' : 'bg-gray-300'}`} />
                    <div className="min-w-0">
                      <p className="font-medium truncate">{project.name}</p>
                      <p className="text-xs text-gray-400 truncate">{project.targetKeyword}</p>
                    </div>
                    {project.id === selectedProjectId && (
                      <ChevronRight className="w-3.5 h-3.5 ml-auto flex-shrink-0" />
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      <nav className="flex-1 overflow-y-auto py-3">
        <div className="space-y-0.5 px-3 mb-4">
          {topMenuItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentPage === item.id;
            return (
              <button
                key={item.id}
                onClick={() => handleNavigate(item.id)}
                className={`flex items-center space-x-3 w-full px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                  isActive
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                }`}
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span>{item.label}</span>
              </button>
            );
          })}
        </div>
        {!selectedProjectId ? (
          <div className="px-6 py-4 text-sm text-gray-400 text-center">
            프로젝트를 선택하면<br />메뉴가 활성화됩니다
          </div>
        ) : (
          menuGroups.map((group) => (
            <div key={group.label} className="mb-4">
              <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider px-6 mb-1">
                {group.label}
              </p>
              <div className="space-y-0.5 px-3">
                {group.items.map((item) => {
                  const Icon = item.icon;
                  const isActive = currentPage === item.id;
                  return (
                    <button
                      key={item.id}
                      onClick={() => handleNavigate(item.id)}
                      className={`flex items-center space-x-3 w-full px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                        isActive
                          ? 'bg-blue-50 text-blue-700'
                          : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
                      }`}
                    >
                      <Icon className="w-4 h-4 flex-shrink-0" />
                      <span>{item.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </nav>

      {IS_DEV && (
        <div className="px-3 pb-2 border-t border-gray-100 pt-2">
          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider px-3 mb-1">개발자</p>
          <div className="space-y-0.5">
            <button
              onClick={() => handleNavigate('migration')}
              className={`flex items-center space-x-3 w-full px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                currentPage === 'migration'
                  ? 'bg-blue-50 text-blue-700'
                  : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'
              }`}
            >
              <Database className="w-4 h-4 flex-shrink-0" />
              <span>Migration</span>
            </button>
          </div>
        </div>
      )}

      <div className="border-t border-gray-200 p-4 flex-shrink-0">
        <div className="flex items-center space-x-3 px-3 py-2 mb-2">
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-gray-900 truncate">{user?.displayName || user?.email}</p>
            <p className="text-xs text-gray-500 truncate">{user?.email}</p>
          </div>
        </div>
        <button
          onClick={handleSignOut}
          className="flex items-center space-x-3 w-full px-3 py-2 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-gray-900 transition-colors"
        >
          <LogOut className="w-4 h-4" />
          <span>Sign Out</span>
        </button>
      </div>
    </div>
  );

  return (
    <>
      <div className="lg:hidden fixed top-0 left-0 right-0 bg-white border-b border-gray-200 z-50">
        <div className="flex items-center justify-between px-4 h-16">
          <div className="flex items-center gap-3">
            <h1 className="text-xl font-bold text-gray-900">GEO Insight</h1>
            {selectedProject && (
              <span className="text-sm text-gray-500 truncate max-w-[140px]">
                / {selectedProject.project.name}
              </span>
            )}
          </div>
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="p-2 rounded-md text-gray-700 hover:bg-gray-100"
          >
            {isMobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 z-40 bg-black bg-opacity-50" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <aside className={`
        fixed top-0 left-0 h-full w-64 bg-white border-r border-gray-200 z-50 transform transition-transform duration-300 ease-in-out
        lg:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <SidebarContent />
      </aside>

      <div className="lg:hidden h-16" />
    </>
  );
}
