import {
  collection,
  doc,
  addDoc,
  getDocs,
  deleteDoc,
  Timestamp
} from 'firebase/firestore';
import { db } from '../config/firebase';
import { COLLECTIONS, SUB_COLLECTIONS } from './firestore';

export type MigrationStatus = 'idle' | 'running' | 'done' | 'error';

export interface CollectionMigrationResult {
  collection: string;
  total: number;
  migrated: number;
  skipped: number;
  errors: number;
}

export interface MigrationResult {
  status: MigrationStatus;
  collections: CollectionMigrationResult[];
  startedAt?: Date;
  finishedAt?: Date;
  errorMessage?: string;
}

export type MigrationProgressCallback = (result: MigrationResult) => void;

const LEGACY_COLLECTIONS = {
  QUERIES: 'jkai011_queries',
  ANSWERS: 'jkai011_answers',
  METRICS: 'jkai011_metrics',
  CONTENTS: 'jkai011_contents'
} as const;

async function migrateCollection(
  projectIds: string[],
  legacyCollectionName: string,
  subCollectionName: string,
  projectIdField: string
): Promise<CollectionMigrationResult> {
  const result: CollectionMigrationResult = {
    collection: legacyCollectionName,
    total: 0,
    migrated: 0,
    skipped: 0,
    errors: 0
  };

  const snapshot = await getDocs(collection(db, legacyCollectionName));
  result.total = snapshot.docs.length;

  for (const docSnap of snapshot.docs) {
    const data = docSnap.data();
    const projectId = data[projectIdField] as string | undefined;

    if (!projectId || !projectIds.includes(projectId)) {
      result.skipped++;
      continue;
    }

    try {
      const targetRef = collection(db, COLLECTIONS.PROJECTS, projectId, subCollectionName);
      await addDoc(targetRef, {
        ...data,
        _migratedAt: Timestamp.now(),
        _legacyId: docSnap.id
      });
      result.migrated++;
    } catch {
      result.errors++;
    }
  }

  return result;
}

export async function runMigration(
  onProgress?: MigrationProgressCallback
): Promise<MigrationResult> {
  const result: MigrationResult = {
    status: 'running',
    collections: [],
    startedAt: new Date()
  };

  onProgress?.(result);

  try {
    const projectsSnapshot = await getDocs(collection(db, COLLECTIONS.PROJECTS));
    const projectIds = projectsSnapshot.docs.map(d => d.id);

    const collectionMappings: Array<{
      legacy: string;
      sub: string;
      projectIdField: string;
    }> = [
      {
        legacy: LEGACY_COLLECTIONS.QUERIES,
        sub: SUB_COLLECTIONS.QUERIES,
        projectIdField: 'projectId'
      },
      {
        legacy: LEGACY_COLLECTIONS.METRICS,
        sub: SUB_COLLECTIONS.METRICS,
        projectIdField: 'projectId'
      },
      {
        legacy: LEGACY_COLLECTIONS.CONTENTS,
        sub: SUB_COLLECTIONS.CONTENTS,
        projectIdField: 'projectId'
      },
      {
        legacy: LEGACY_COLLECTIONS.ANSWERS,
        sub: SUB_COLLECTIONS.ANSWERS,
        projectIdField: 'queryId'
      }
    ];

    for (const mapping of collectionMappings) {
      const colResult = await migrateCollection(
        projectIds,
        mapping.legacy,
        mapping.sub,
        mapping.projectIdField
      );
      result.collections.push(colResult);
      onProgress?.({ ...result, collections: [...result.collections] });
    }

    result.status = 'done';
    result.finishedAt = new Date();
  } catch (err) {
    result.status = 'error';
    result.errorMessage = err instanceof Error ? err.message : String(err);
    result.finishedAt = new Date();
  }

  onProgress?.(result);
  return result;
}

export async function getLegacyCollectionCounts(): Promise<Record<string, number>> {
  const counts: Record<string, number> = {};

  for (const [key, name] of Object.entries(LEGACY_COLLECTIONS)) {
    try {
      const snapshot = await getDocs(collection(db, name));
      counts[key] = snapshot.docs.length;
    } catch {
      counts[key] = -1;
    }
  }

  return counts;
}

export async function deleteLegacyCollection(collectionName: string): Promise<number> {
  const snapshot = await getDocs(collection(db, collectionName));
  let deleted = 0;

  for (const docSnap of snapshot.docs) {
    await deleteDoc(doc(db, collectionName, docSnap.id));
    deleted++;
  }

  return deleted;
}

export const LEGACY_COLLECTION_NAMES = LEGACY_COLLECTIONS;
