import { simulateAIAnswer } from '../services/openai';
import { getQueryDoc, getProject, createAnswer, createMetric } from '../db/firestore';
import { extractEntities, findEntityPositions, isRecommended, calculateScore } from '../utils/parser';
import { logger } from '../utils/logger';

export interface AnswerWorkerPayload {
  jobId: string;
  projectId: string;
  queryId: string;
  competitors?: string[];
}

export const processAnswer = async (payload: AnswerWorkerPayload) => {
  const { jobId, projectId, queryId, competitors = [] } = payload;

  try {
    await logger.info(jobId, `Processing answer for query: ${queryId}`);

    const queryDoc = await getQueryDoc(projectId, queryId);
    if (!queryDoc) {
      throw new Error(`Query not found: ${queryId}`);
    }

    const project = await getProject(projectId);
    if (!project) {
      throw new Error(`Project not found: ${projectId}`);
    }

    const targetBrand = project.targetKeyword;

    await logger.info(jobId, `Simulating AI answer for: ${queryDoc.text}`);

    const answerText = await simulateAIAnswer(queryDoc.text);

    const entities = extractEntities(answerText, targetBrand, competitors);
    const positions = findEntityPositions(answerText, entities);
    const mention = entities.includes(targetBrand);
    const isRec = mention ? isRecommended(answerText, targetBrand) : false;

    const answerId = await createAnswer(projectId, {
      queryId,
      platform: 'other',
      rawAnswer: answerText,
      mentionedEntities: entities,
      targetMentioned: mention,
      recommendationPresence: isRec,
      comparisonPresence: false,
      entityPositions: positions
    });

    await logger.info(jobId, `Answer created: ${answerId}`);

    const position = positions[targetBrand] || null;
    const score = calculateScore(mention, position, isRec);

    const metricId = await createMetric(projectId, {
      queryId,
      platform: 'other',
      mention,
      position,
      isRecommended: isRec,
      competitors: entities.filter(e => e !== targetBrand),
      score
    });

    await logger.info(jobId, `Metric created: ${metricId}, Score: ${score}`);

    return {
      answerId,
      metricId,
      mention,
      score
    };
  } catch (error) {
    await logger.error(jobId, `Failed to process answer: ${error}`);
    throw error;
  }
};

export const processAnswerBatch = async (
  jobId: string,
  projectId: string,
  queryIds: string[],
  competitors: string[] = []
) => {
  const results = [];

  for (const queryId of queryIds) {
    try {
      const result = await processAnswer({ jobId, projectId, queryId, competitors });
      results.push({ queryId, success: true, ...result });
    } catch (error) {
      results.push({ queryId, success: false, error: String(error) });
    }
  }

  return results;
};
