export const extractEntities = (text: string, targetBrand: string, competitors: string[] = []): string[] => {
  const allBrands = [targetBrand, ...competitors];
  const foundEntities: string[] = [];

  for (const brand of allBrands) {
    const regex = new RegExp(brand, 'gi');
    if (regex.test(text)) {
      foundEntities.push(brand);
    }
  }

  return foundEntities;
};

export const findEntityPositions = (text: string, entities: string[]): Record<string, number> => {
  const positions: Record<string, number> = {};
  const sentences = text.split(/[.!?]\s+/);

  for (const entity of entities) {
    for (let i = 0; i < sentences.length; i++) {
      const regex = new RegExp(entity, 'gi');
      if (regex.test(sentences[i])) {
        positions[entity] = i + 1;
        break;
      }
    }
  }

  return positions;
};

export const isRecommended = (text: string, brand: string): boolean => {
  const keywords = ['추천', '좋다', '최고', '인기', '베스트', '우수', '탁월'];

  const sentences = text.split(/[.!?]\s+/);

  for (const sentence of sentences) {
    const regex = new RegExp(brand, 'gi');
    if (regex.test(sentence)) {
      for (const keyword of keywords) {
        if (sentence.includes(keyword)) {
          return true;
        }
      }
    }
  }

  return false;
};

export const calculateScore = (
  mention: boolean,
  position: number | null,
  isRec: boolean
): number => {
  let score = 0;

  if (mention) score += 40;

  if (position !== null) {
    if (position <= 3) score += 40;
    else if (position <= 5) score += 20;
    else score += 10;
  }

  if (isRec) score += 20;

  return score;
};
