import { useState } from "react";
import { Zap, AlertCircle, Settings } from "lucide-react";

type Frequency = "daily" | "weekly" | "monthly";

interface AutoCard {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  hasContentType?: boolean;
}

const cards: AutoCard[] = [
  {
    id: "simulation",
    title: "자동 시뮬레이션",
    description: "정기적으로 AI 답변 시뮬레이션을 실행합니다",
    icon: <Zap className="w-5 h-5" />,
  },
  {
    id: "analysis",
    title: "자동 문제 분석",
    description: "정기적으로 AI 답변 데이터를 분석해 문제를 탐지합니다",
    icon: <AlertCircle className="w-5 h-5" />,
  },
  {
    id: "content",
    title: "자동 콘텐츠 생성",
    description: "탐지된 문제를 바탕으로 콘텐츠를 자동 생성합니다",
    icon: <Settings className="w-5 h-5" />,
    hasContentType: true,
  },
];

const frequencyOptions: { value: Frequency; label: string }[] = [
  { value: "daily", label: "매일" },
  { value: "weekly", label: "매주" },
  { value: "monthly", label: "매월" },
];

const contentTypeOptions = [
  { value: "qa", label: "Q&A 콘텐츠" },
  { value: "list", label: "추천 리스트" },
  { value: "compare", label: "비교 콘텐츠" },
];

export default function AutomationPage() {
  const [enabled, setEnabled] = useState<Record<string, boolean>>({
    simulation: false,
    analysis: false,
    content: false,
  });
  const [frequency, setFrequency] = useState<Record<string, Frequency>>({
    simulation: "weekly",
    analysis: "weekly",
    content: "weekly",
  });
  const [contentType, setContentType] = useState("qa");

  const toggleEnabled = (id: string) => {
    setEnabled((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const setFreq = (id: string, value: Frequency) => {
    setFrequency((prev) => ({ ...prev, [id]: value }));
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800">Automation</h1>
        <p className="text-sm text-slate-500 mt-1">자동화 설정 및 스케줄 관리</p>
      </div>

      <div className="space-y-4 mb-6">
        {cards.map((card) => (
          <div
            key={card.id}
            className="bg-white rounded-xl border border-slate-200 p-5"
          >
            <div className="flex items-start justify-between gap-4">
              <div className="flex items-start gap-3">
                <div className="p-2 bg-slate-100 text-slate-600 rounded-lg mt-0.5">
                  {card.icon}
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-slate-800">{card.title}</h3>
                  <p className="text-xs text-slate-500 mt-0.5">{card.description}</p>
                </div>
              </div>

              <button
                onClick={() => toggleEnabled(card.id)}
                className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
                  enabled[card.id] ? "bg-blue-600" : "bg-slate-200"
                }`}
              >
                <span
                  className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${
                    enabled[card.id] ? "translate-x-6" : "translate-x-1"
                  }`}
                />
              </button>
            </div>

            <div className="mt-4 flex items-center gap-4">
              <div className="flex items-center gap-2">
                <label className="text-xs text-slate-500">실행 주기</label>
                <select
                  value={frequency[card.id]}
                  onChange={(e) => setFreq(card.id, e.target.value as Frequency)}
                  disabled={!enabled[card.id]}
                  className="text-xs border border-slate-200 rounded-lg px-2 py-1.5 text-slate-700 disabled:opacity-50 disabled:bg-slate-50 focus:outline-none focus:ring-1 focus:ring-blue-500"
                >
                  {frequencyOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>

              {card.hasContentType && (
                <div className="flex items-center gap-2">
                  <label className="text-xs text-slate-500">콘텐츠 유형</label>
                  <select
                    value={contentType}
                    onChange={(e) => setContentType(e.target.value)}
                    disabled={!enabled[card.id]}
                    className="text-xs border border-slate-200 rounded-lg px-2 py-1.5 text-slate-700 disabled:opacity-50 disabled:bg-slate-50 focus:outline-none focus:ring-1 focus:ring-blue-500"
                  >
                    {contentTypeOptions.map((opt) => (
                      <option key={opt.value} value={opt.value}>
                        {opt.label}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              <div className="ml-auto text-xs text-slate-400">
                마지막 실행: <span className="font-medium">미실행</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="flex items-start gap-2 p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm text-slate-500">
        <AlertCircle className="w-4 h-4 mt-0.5 shrink-0 text-slate-400" />
        자동화 기능은 Firebase Cloud Functions 연동 후 활성화됩니다.
      </div>
    </div>
  );
}
