import { generateContent, generateContentVariations } from '../services/openai';
import { getQueryDoc, getProject, createContent } from '../db/firestore';
import { logger } from '../utils/logger';

export interface ContentWorkerPayload {
  jobId: string;
  projectId: string;
  queryId: string;
  contentType: 'qa' | 'list' | 'compare';
  generateVariations?: boolean;
}

export const processContent = async (payload: ContentWorkerPayload) => {
  const { jobId, projectId, queryId, contentType, generateVariations = false } = payload;

  try {
    await logger.info(jobId, `Processing content for query: ${queryId}, type: ${contentType}`);

    const queryDoc = await getQueryDoc(projectId, queryId);
    if (!queryDoc) {
      throw new Error(`Query not found: ${queryId}`);
    }

    const project = await getProject(projectId);
    if (!project) {
      throw new Error(`Project not found: ${projectId}`);
    }

    const targetBrand = project.targetKeyword;

    await logger.info(jobId, `Generating ${contentType} content for: ${queryDoc.text}`);

    const content = await generateContent(queryDoc.text, targetBrand, contentType);

    const contentId = await createContent(projectId, {
      queryId,
      type: contentType,
      content,
      status: 'generated'
    });

    await logger.info(jobId, `Content created: ${contentId}`);

    const variationIds: string[] = [];

    if (generateVariations) {
      await logger.info(jobId, `Generating content variations`);

      const variations = await generateContentVariations(content, 3);

      for (let i = 0; i < variations.length; i++) {
        const varId = await createContent(projectId, {
          queryId,
          type: contentType,
          content: variations[i],
          variationIndex: i + 1,
          status: 'generated'
        });
        variationIds.push(varId);
      }

      await logger.info(jobId, `Created ${variations.length} variations`);
    }

    return {
      contentId,
      variationIds
    };
  } catch (error) {
    await logger.error(jobId, `Failed to process content: ${error}`);
    throw error;
  }
};

export const processContentBatch = async (
  jobId: string,
  projectId: string,
  queryIds: string[],
  contentType: 'qa' | 'list' | 'compare',
  generateVariations = false
) => {
  const results = [];

  for (const queryId of queryIds) {
    try {
      const result = await processContent({ jobId, projectId, queryId, contentType, generateVariations });
      results.push({ queryId, success: true, ...result });
    } catch (error) {
      results.push({ queryId, success: false, error: String(error) });
    }
  }

  return results;
};
