import { useState, useEffect } from "react";
import { RefreshCw, CheckCircle, XCircle, ChevronDown, ChevronUp, Play } from "lucide-react";
import { useProject } from "../contexts/ProjectContext";
import { getAnswersByProject, Answer } from "../db/firestore";
import { handleRunSimulation } from "../api/runSimulation";

export default function AIAnswersPage() {
  const { selectedProject, selectedProjectId, loading: projectLoading } = useProject();
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [loadingAnswers, setLoadingAnswers] = useState(false);
  const [running, setRunning] = useState(false);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (!selectedProjectId) return;
    setLoadingAnswers(true);
    getAnswersByProject(selectedProjectId)
      .then((data) => setAnswers(data))
      .finally(() => setLoadingAnswers(false));
  }, [selectedProjectId]);

  const toggleExpand = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const onRunSimulation = async () => {
    if (!selectedProject || !selectedProjectId) return;
    const queryIds = selectedProject.queries.map((q) => q.id).filter((id): id is string => !!id);
    setRunning(true);
    try {
      await handleRunSimulation({ projectId: selectedProjectId, queryIds });
      const data = await getAnswersByProject(selectedProjectId);
      setAnswers(data);
    } finally {
      setRunning(false);
    }
  };

  if (projectLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!selectedProject) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-slate-500 text-sm">프로젝트를 먼저 선택하세요.</p>
      </div>
    );
  }

  const totalAnswers = answers.length;
  const mentionCount = answers.filter((a) => a.targetMentioned).length;
  const mentionRate = totalAnswers > 0 ? Math.round((mentionCount / totalAnswers) * 100) : 0;
  const recommendCount = answers.filter((a) => a.recommendationPresence).length;
  const recommendRate = totalAnswers > 0 ? Math.round((recommendCount / totalAnswers) * 100) : 0;
  const avgScore =
    totalAnswers > 0
      ? Math.round(answers.reduce((sum, _a) => sum + 0, 0) / totalAnswers)
      : 0;

  const getQueryText = (queryId: string) => {
    const q = selectedProject.queries.find((q) => q.id === queryId);
    return q ? q.text : queryId;
  };

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">AI 답변 시뮬레이션</h1>
          <p className="text-sm text-slate-500 mt-1">{selectedProject.project.name}</p>
        </div>
        <button
          onClick={onRunSimulation}
          disabled={running}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 disabled:opacity-60 transition-colors"
        >
          {running ? (
            <RefreshCw className="w-4 h-4 animate-spin" />
          ) : (
            <Play className="w-4 h-4" />
          )}
          시뮬레이션 실행
        </button>
      </div>

      {totalAnswers > 0 && (
        <div className="grid grid-cols-4 gap-4 mb-6">
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <p className="text-xs text-slate-500 mb-1">총 답변</p>
            <p className="text-2xl font-bold text-slate-800">{totalAnswers}</p>
          </div>
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <p className="text-xs text-slate-500 mb-1">언급률</p>
            <p className="text-2xl font-bold text-blue-600">{mentionRate}%</p>
          </div>
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <p className="text-xs text-slate-500 mb-1">추천 포함률</p>
            <p className="text-2xl font-bold text-green-600">{recommendRate}%</p>
          </div>
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <p className="text-xs text-slate-500 mb-1">평균 점수</p>
            <p className="text-2xl font-bold text-slate-800">{avgScore}</p>
          </div>
        </div>
      )}

      {loadingAnswers ? (
        <div className="flex items-center justify-center h-48">
          <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
        </div>
      ) : answers.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-64 bg-white rounded-xl border border-slate-200">
          <p className="text-slate-400 text-sm mb-4">아직 시뮬레이션 결과가 없습니다.</p>
          <button
            onClick={onRunSimulation}
            disabled={running}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 disabled:opacity-60 transition-colors"
          >
            {running ? (
              <RefreshCw className="w-4 h-4 animate-spin" />
            ) : (
              <Play className="w-4 h-4" />
            )}
            시뮬레이션 실행
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {answers.map((answer) => {
            const isExpanded = expandedIds.has(answer.id ?? "");
            return (
              <div
                key={answer.id}
                className="bg-white rounded-xl border border-slate-200 p-4"
              >
                <div className="flex items-start justify-between gap-4 mb-3">
                  <p className="text-sm font-medium text-slate-700 flex-1">
                    {getQueryText(answer.queryId)}
                  </p>
                  <div className="flex items-center gap-2 shrink-0">
                    {answer.targetMentioned ? (
                      <span className="flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 text-xs rounded-full">
                        <CheckCircle className="w-3 h-3" />
                        언급됨
                      </span>
                    ) : (
                      <span className="flex items-center gap-1 px-2 py-0.5 bg-red-100 text-red-600 text-xs rounded-full">
                        <XCircle className="w-3 h-3" />
                        미언급
                      </span>
                    )}
                    {answer.recommendationPresence && (
                      <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded-full">
                        추천 포함
                      </span>
                    )}
                    
                  </div>
                </div>

                <div className="text-sm text-slate-600">
                  {isExpanded ? (
                    <p className="whitespace-pre-wrap">{answer.rawAnswer}</p>
                  ) : (
                    <p className="line-clamp-2">{answer.rawAnswer}</p>
                  )}
                </div>

                {answer.rawAnswer && answer.rawAnswer.length > 150 && (
                  <button
                    onClick={() => toggleExpand(answer.id ?? "")}
                    className="flex items-center gap-1 mt-2 text-xs text-blue-600 hover:text-blue-700"
                  >
                    {isExpanded ? (
                      <>
                        <ChevronUp className="w-3 h-3" />
                        접기
                      </>
                    ) : (
                      <>
                        <ChevronDown className="w-3 h-3" />
                        더 보기
                      </>
                    )}
                  </button>
                )}

                {answer.mentionedEntities && answer.mentionedEntities.length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-3">
                    {answer.mentionedEntities.map((entity, i) => (
                      <span
                        key={i}
                        className="px-2 py-0.5 bg-slate-100 text-slate-500 text-xs rounded"
                      >
                        {entity}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
