import { useState, useEffect } from 'react';
import { Users, Mail, Trash2, X, UserPlus } from 'lucide-react';
import { getProjectMembers, addProjectMember, removeProjectMember, ProjectMember, Project } from '../db/firestore';
import { useAuth } from '../contexts/AuthContext';

interface ProjectShareProps {
  project: Project;
  onClose: () => void;
}

export const ProjectShare = ({ project, onClose }: ProjectShareProps) => {
  const { user } = useAuth();
  const [members, setMembers] = useState<ProjectMember[]>([]);
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<'editor' | 'viewer'>('viewer');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [loadingMembers, setLoadingMembers] = useState(true);

  const isOwner = user?.uid === project.userId;

  useEffect(() => {
    loadMembers();
  }, [project.id]);

  const loadMembers = async () => {
    try {
      setLoadingMembers(true);
      const projectMembers = await getProjectMembers(project.id!);
      setMembers(projectMembers);
    } catch (error) {
      console.error('Error loading members:', error);
    } finally {
      setLoadingMembers(false);
    }
  };

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    setLoading(true);
    setError('');

    try {
      await addProjectMember(project.id!, email.trim(), role);
      setEmail('');
      setRole('viewer');
      await loadMembers();
    } catch (error) {
      setError(error instanceof Error ? error.message : '멤버 추가 실패');
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveMember = async (memberId: string) => {
    if (!window.confirm('이 멤버를 프로젝트에서 제거하시겠습니까?')) return;

    try {
      await removeProjectMember(project.id!, memberId);
      await loadMembers();
    } catch (error) {
      alert(error instanceof Error ? error.message : '멤버 제거 실패');
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        <div className="p-6 border-b border-slate-200 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Users className="w-6 h-6 text-blue-600" />
            <div>
              <h2 className="text-xl font-bold text-slate-900">프로젝트 공유</h2>
              <p className="text-sm text-slate-600">{project.name}</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {isOwner ? (
            <>
              <form onSubmit={handleAddMember} className="mb-6">
                <label className="block text-sm font-medium text-slate-700 mb-2">
                  팀원 초대
                </label>
                <div className="flex gap-3">
                  <div className="flex-1 relative">
                    <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="이메일 주소 입력"
                      className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      disabled={loading}
                    />
                  </div>
                  <select
                    value={role}
                    onChange={(e) => setRole(e.target.value as 'editor' | 'viewer')}
                    className="px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    disabled={loading}
                  >
                    <option value="viewer">보기 권한</option>
                    <option value="editor">편집 권한</option>
                  </select>
                  <button
                    type="submit"
                    disabled={loading || !email.trim()}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-slate-300 disabled:cursor-not-allowed transition-colors flex items-center gap-2 whitespace-nowrap"
                  >
                    <UserPlus className="w-4 h-4" />
                    초대
                  </button>
                </div>
                {error && (
                  <p className="mt-2 text-sm text-red-600">{error}</p>
                )}
              </form>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
                <h4 className="text-sm font-medium text-blue-900 mb-2">권한 안내</h4>
                <ul className="text-sm text-blue-800 space-y-1">
                  <li>• <strong>보기 권한:</strong> 프로젝트 데이터를 조회만 할 수 있습니다</li>
                  <li>• <strong>편집 권한:</strong> 프로젝트 데이터를 조회하고 수정할 수 있습니다</li>
                </ul>
              </div>
            </>
          ) : (
            <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 mb-6">
              <p className="text-sm text-slate-600">
                이 프로젝트는 공유받은 프로젝트입니다. 소유자만 멤버를 관리할 수 있습니다.
              </p>
            </div>
          )}

          <div>
            <h3 className="text-sm font-medium text-slate-700 mb-3">
              프로젝트 멤버 ({members.length + 1})
            </h3>

            {loadingMembers ? (
              <div className="text-center py-8">
                <div className="inline-block w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
              </div>
            ) : (
              <div className="space-y-2">
                <div className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                  <div className="flex items-center gap-3">
                    {isOwner && user?.photoURL ? (
                      <img
                        src={user.photoURL}
                        alt={user.displayName || user.email || '소유자'}
                        className="w-10 h-10 rounded-full"
                      />
                    ) : (
                      <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-semibold">
                        {isOwner ? (user?.email?.[0]?.toUpperCase() || '?') : '?'}
                      </div>
                    )}
                    <div>
                      {isOwner ? (
                        <>
                          <p className="text-sm font-medium text-slate-900">
                            {user?.displayName || user?.email || '소유자'}
                          </p>
                          {user?.displayName && user?.email && (
                            <p className="text-xs text-slate-500">{user.email}</p>
                          )}
                        </>
                      ) : (
                        <p className="text-sm font-medium text-slate-900">소유자</p>
                      )}
                    </div>
                  </div>
                  <span className="text-xs font-medium text-blue-600 bg-blue-100 px-2 py-1 rounded">
                    소유자
                  </span>
                </div>

                {members.map((member) => (
                  <div key={member.id} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-lg">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-slate-300 text-slate-600 rounded-full flex items-center justify-center font-semibold">
                        {member.userEmail[0].toUpperCase()}
                      </div>
                      <div>
                        <p className="text-sm font-medium text-slate-900">{member.userEmail}</p>
                        <p className="text-xs text-slate-500">
                          {member.role === 'editor' ? '편집 권한' : '보기 권한'}
                        </p>
                      </div>
                    </div>
                    {isOwner && (
                      <button
                        onClick={() => handleRemoveMember(member.id!)}
                        className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        title="멤버 제거"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                ))}

                {members.length === 0 && (
                  <div className="text-center py-8 text-slate-500">
                    <Users className="w-12 h-12 mx-auto mb-2 opacity-50" />
                    <p className="text-sm">아직 초대된 멤버가 없습니다</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 border-t border-slate-200 bg-slate-50">
          <button
            onClick={onClose}
            className="w-full px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-700 transition-colors"
          >
            닫기
          </button>
        </div>
      </div>
    </div>
  );
};
