import { askLLM } from '../services/openai';
import { Metric, QueryDoc, createProblem, getProblemsByProject, updateProblem } from '../db/firestore';
import { Timestamp } from 'firebase/firestore';

export interface AnalysisInput {
  projectId: string;
  targetKeyword: string;
  queries: QueryDoc[];
  metrics: Metric[];
}

interface DetectedProblem {
  problemType:
    | 'region_signal_gap'
    | 'attribute_signal_gap'
    | 'recommendation_phrase_gap'
    | 'competitor_dominance'
    | 'coverage_gap'
    | 'platform_bias';
  scopeType?: string;
  scopeKey?: string;
  title: string;
  summary: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  score: number;
  tags: string[];
  recommendedNextActionType: string;
  recommendedNextActionPayload: Record<string, any>;
}

function detectProblemsFromMetrics(
  metrics: Metric[],
  queries: QueryDoc[]
): DetectedProblem[] {
  const problems: DetectedProblem[] = [];

  if (metrics.length === 0) return problems;

  const mentionRate = metrics.filter(m => m.mention).length / metrics.length;
  const recommendRate = metrics.filter(m => m.isRecommended).length / metrics.length;

  if (mentionRate < 0.3) {
    problems.push({
      problemType: 'coverage_gap',
      title: '전반적인 AI 노출 부족',
      summary: `현재 AI 답변의 ${(mentionRate * 100).toFixed(0)}%에서만 노출되고 있습니다. 전체적인 온라인 신호 강화가 필요합니다.`,
      severity: mentionRate < 0.1 ? 'critical' : 'high',
      score: Math.round((1 - mentionRate) * 100),
      tags: ['노출률', '신호부족'],
      recommendedNextActionType: 'generate_content',
      recommendedNextActionPayload: { contentType: 'qa', targetMentionRate: 0.6 }
    });
  }

  if (mentionRate >= 0.3 && recommendRate < 0.2) {
    problems.push({
      problemType: 'recommendation_phrase_gap',
      title: '추천 문구 부재',
      summary: `노출은 되고 있으나 추천 형태로 언급되는 비율이 ${(recommendRate * 100).toFixed(0)}%에 불과합니다. 추천 맥락의 콘텐츠 생산이 필요합니다.`,
      severity: 'high',
      score: Math.round((1 - recommendRate) * 80),
      tags: ['추천부족', '콘텐츠'],
      recommendedNextActionType: 'generate_content',
      recommendedNextActionPayload: { contentType: 'list', includeRecommendationPhrases: true }
    });
  }

  const competitorMentions: Record<string, number> = {};
  metrics.forEach(m => {
    m.competitors.forEach(c => {
      competitorMentions[c] = (competitorMentions[c] || 0) + 1;
    });
  });

  const dominantCompetitors = Object.entries(competitorMentions)
    .filter(([, count]) => count > metrics.length * 0.5)
    .map(([name]) => name);

  if (dominantCompetitors.length > 0) {
    problems.push({
      problemType: 'competitor_dominance',
      title: `경쟁사 지배적 노출: ${dominantCompetitors.join(', ')}`,
      summary: `${dominantCompetitors.join(', ')}가 AI 답변의 50% 이상에서 언급되고 있습니다. 비교 콘텐츠를 통한 차별화가 필요합니다.`,
      severity: 'high',
      score: 75,
      tags: ['경쟁사', '차별화'],
      recommendedNextActionType: 'generate_content',
      recommendedNextActionPayload: { contentType: 'compare', competitors: dominantCompetitors }
    });
  }

  const regionQueries = queries.filter(q => q.regionPrimary);
  const regionMetrics = metrics.filter((_, i) => {
    const q = queries[i];
    return q && q.regionPrimary;
  });

  if (regionQueries.length > 0 && regionMetrics.length > 0) {
    const regionMentionRate = regionMetrics.filter(m => m.mention).length / regionMetrics.length;
    if (regionMentionRate < mentionRate * 0.7) {
      const regions = [...new Set(regionQueries.map(q => q.regionPrimary!))];
      problems.push({
        problemType: 'region_signal_gap',
        title: `지역 신호 부족: ${regions.slice(0, 3).join(', ')}`,
        summary: `지역 기반 질문에서의 노출률(${(regionMentionRate * 100).toFixed(0)}%)이 전체 평균보다 낮습니다. 지역 특화 콘텐츠 보강이 필요합니다.`,
        severity: 'medium',
        score: 60,
        tags: ['지역', '로컬SEO'],
        recommendedNextActionType: 'generate_content',
        recommendedNextActionPayload: { contentType: 'qa', regions }
      });
    }
  }

  return problems;
}

export async function analyzeProblems(input: AnalysisInput): Promise<string[]> {
  const { projectId, queries, metrics } = input;

  const detectedProblems = detectProblemsFromMetrics(metrics, queries);

  if (detectedProblems.length === 0) return [];

  const existingProblems = await getProblemsByProject(projectId);
  const now = Timestamp.now();

  const createdIds: string[] = [];

  for (const problem of detectedProblems) {
    const existing = existingProblems.find(
      ep => ep.problemType === problem.problemType && ep.status !== 'resolved'
    );

    if (existing && existing.id) {
      await updateProblem(projectId, existing.id, {
        score: problem.score,
        severity: problem.severity,
        summary: problem.summary,
        lastDetectedAt: now
      });
      createdIds.push(existing.id);
    } else {
      const newId = await createProblem(projectId, {
        problemType: problem.problemType,
        scopeType: problem.scopeType,
        scopeKey: problem.scopeKey,
        title: problem.title,
        summary: problem.summary,
        severity: problem.severity,
        score: problem.score,
        status: 'active',
        tags: problem.tags,
        recommendedNextActionType: problem.recommendedNextActionType,
        recommendedNextActionPayload: problem.recommendedNextActionPayload,
        firstDetectedAt: now,
        lastDetectedAt: now,
        resolvedAt: null
      });
      createdIds.push(newId);
    }
  }

  return createdIds;
}

export async function getAIProblemSuggestion(
  problem: { title: string; summary: string; problemType: string },
  targetKeyword: string
): Promise<string> {
  const prompt = `다음 GEO(Generative Engine Optimization) 문제에 대한 해결 전략을 제안해주세요.

비즈니스: ${targetKeyword}
문제 유형: ${problem.problemType}
문제 제목: ${problem.title}
문제 설명: ${problem.summary}

다음 내용을 포함하는 구체적인 해결 전략을 300자 이내로 작성해주세요:
1. 핵심 원인
2. 즉시 실행 가능한 액션 1-2가지
3. 기대 효과`;

  return askLLM(prompt);
}
