import { useState, useEffect } from "react";
import { RefreshCw, FileText, List, GitCompare, BookOpen, ChevronDown, ChevronUp } from "lucide-react";
import { useProject } from "../contexts/ProjectContext";
import { getContentsByProject, Content } from "../db/firestore";
import { handleGenerateContent } from "../api/generateContent";

type ContentType = "qa" | "list" | "compare";

interface Template {
  type: ContentType;
  label: string;
  description: string;
  icon: React.ReactNode;
}

const templates: Template[] = [
  {
    type: "qa",
    label: "Q&A 콘텐츠",
    description: "질문에 답하는 자연스러운 문답 형식",
    icon: <FileText className="w-5 h-5" />,
  },
  {
    type: "list",
    label: "추천 리스트",
    description: "우리를 상위에 포함한 추천 목록",
    icon: <List className="w-5 h-5" />,
  },
  {
    type: "compare",
    label: "비교 콘텐츠",
    description: "경쟁사와 비교하여 우리 강점 부각",
    icon: <GitCompare className="w-5 h-5" />,
  },
  {
    type: "qa",
    label: "아티클",
    description: "정보성 아티클 형식의 콘텐츠",
    icon: <BookOpen className="w-5 h-5" />,
  },
];

const typeLabels: Record<ContentType, string> = {
  qa: "Q&A",
  list: "리스트",
  compare: "비교",
};

const statusConfig: Record<string, { label: string; bg: string; text: string }> = {
  draft: { label: "초안", bg: "bg-slate-100", text: "text-slate-600" },
  published: { label: "게시됨", bg: "bg-green-100", text: "text-green-700" },
  archived: { label: "보관됨", bg: "bg-gray-100", text: "text-gray-500" },
};

export default function ActionsPage() {
  const { selectedProject, selectedProjectId, loading: projectLoading } = useProject();
  const [contents, setContents] = useState<Content[]>([]);
  const [loadingContents, setLoadingContents] = useState(false);
  const [generatingType, setGeneratingType] = useState<string | null>(null);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (!selectedProjectId) return;
    setLoadingContents(true);
    getContentsByProject(selectedProjectId)
      .then((data) => setContents(data))
      .finally(() => setLoadingContents(false));
  }, [selectedProjectId]);

  const onGenerate = async (type: ContentType, templateLabel: string) => {
    if (!selectedProject || !selectedProjectId) return;
    const queryIds = selectedProject.queries.map((q) => q.id);
    const key = `${type}-${templateLabel}`;
    setGeneratingType(key);
    try {
      await handleGenerateContent({ projectId: selectedProjectId!, queryIds: queryIds.filter((id): id is string => !!id), contentType: type });
      const data = await getContentsByProject(selectedProjectId);
      setContents(data);
    } finally {
      setGeneratingType(null);
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  if (projectLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-6 h-6 animate-spin text-blue-600" />
      </div>
    );
  }

  if (!selectedProject) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-slate-500 text-sm">프로젝트를 먼저 선택하세요.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800">Actions</h1>
        <p className="text-sm text-slate-500 mt-1">{selectedProject.project.name}</p>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-8">
        {templates.map((tpl, idx) => {
          const key = `${tpl.type}-${tpl.label}`;
          const isGenerating = generatingType === key;
          return (
            <div
              key={idx}
              className="bg-white rounded-xl border border-slate-200 p-5 flex flex-col gap-3"
            >
              <div className="flex items-start gap-3">
                <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">{tpl.icon}</div>
                <div className="flex-1">
                  <h3 className="text-sm font-semibold text-slate-800">{tpl.label}</h3>
                  <p className="text-xs text-slate-500 mt-0.5">{tpl.description}</p>
                </div>
              </div>
              <button
                onClick={() => onGenerate(tpl.type, tpl.label)}
                disabled={isGenerating || generatingType !== null}
                className="flex items-center justify-center gap-2 w-full py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700 disabled:opacity-60 transition-colors"
              >
                {isGenerating && <RefreshCw className="w-4 h-4 animate-spin" />}
                생성
              </button>
            </div>
          );
        })}
      </div>

      <div>
        <h2 className="text-base font-semibold text-slate-700 mb-3">생성된 콘텐츠</h2>

        {loadingContents ? (
          <div className="flex items-center justify-center h-32">
            <RefreshCw className="w-5 h-5 animate-spin text-blue-600" />
          </div>
        ) : contents.length === 0 ? (
          <div className="flex items-center justify-center h-32 bg-white rounded-xl border border-slate-200">
            <p className="text-slate-400 text-sm">아직 생성된 콘텐츠가 없습니다.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {contents.map((content) => {
              const isExpanded = expandedIds.has(content.id ?? "");
              const stCfg = statusConfig[content.status] ?? statusConfig.draft;
              const typLabel = typeLabels[content.type as ContentType] ?? content.type;
              const preview = content.content?.slice(0, 200) ?? "";
              const hasMore = (content.content?.length ?? 0) > 200;

              return (
                <div
                  key={content.id}
                  className="bg-white rounded-xl border border-slate-200 p-4"
                >
                  <div className="flex items-center gap-2 mb-2">
                    <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded-full font-medium">
                      {typLabel}
                    </span>
                    <span
                      className={`px-2 py-0.5 rounded-full text-xs font-medium ${stCfg.bg} ${stCfg.text}`}
                    >
                      {stCfg.label}
                    </span>
                  </div>

                  <p className="text-sm text-slate-600 whitespace-pre-wrap">
                    {isExpanded ? content.content : preview}
                    {!isExpanded && hasMore && "..."}
                  </p>

                  {hasMore && (
                    <button
                      onClick={() => toggleExpand(content.id ?? "")}
                      className="flex items-center gap-1 mt-2 text-xs text-blue-600 hover:text-blue-700"
                    >
                      {isExpanded ? (
                        <>
                          <ChevronUp className="w-3 h-3" />
                          접기
                        </>
                      ) : (
                        <>
                          <ChevronDown className="w-3 h-3" />
                          전체 보기
                        </>
                      )}
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
